t.html:
{{IMG:pension-catchup-payment|}}
<p><strong>국민연금 추납(추후납부) 보험료는 ‘신청한 달의 기준소득월액 × 납부기한이 속한 달의 보험료율 × 추납 개월 수’예요. 기준소득월액이 200만원이면 1개월분이 2026년 보험료율 9.5%로 19만원, 2027년 10%로 20만원이라 60개월을 추납하면 1,140만원과 1,200만원으로 60만원 차이가 나요.</strong> 아래 계산기에 기준소득월액과 추납 개월 수를 넣으면 총 추납액, 분할 납부 때 한 번에 내는 돈, 2026년과 2027년에 낼 때의 차액을 바로 볼 수 있어요.</p>
<!-- 국민연금 추납 보험료 계산기 위젯 시작 : 티스토리/블로거/워드프레스 글의 HTML 모드에 그대로 붙여 넣으세요 -->
<div class="kpc" data-kpc>
  <style>
    .kpc{--kpc-accent:#3b6ef5;--kpc-accent-soft:#eef3ff;--kpc-text:#1d2433;--kpc-sub:#6b7385;--kpc-line:#e3e7ef;--kpc-bg:#fff;--kpc-bad:#e0565b;
      box-sizing:border-box;max-width:520px;margin:24px auto;padding:24px;border:1px solid var(--kpc-line);border-radius:20px;background:var(--kpc-bg);
      color:var(--kpc-text);font-family:-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo","Pretendard","Noto Sans KR","Malgun Gothic",sans-serif;
      line-height:1.5;text-align:left;box-shadow:0 6px 24px rgba(30,45,90,.06)}
    .kpc [hidden]{display:none!important}
    .kpc *,.kpc *::before,.kpc *::after{box-sizing:border-box;margin:0;padding:0;font-family:inherit}
    .kpc .kpc-title{font-size:20px;font-weight:700;letter-spacing:-.02em;word-break:keep-all}
    .kpc .kpc-desc{margin-top:4px;font-size:14px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-label{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:20px 0 8px;font-size:14px;font-weight:600;color:var(--kpc-text);word-break:keep-all}
    .kpc .kpc-label small{font-weight:500;color:var(--kpc-sub)}
    .kpc .kpc-row{display:flex;gap:8px}
    .kpc .kpc-field{position:relative;flex:1}
    .kpc .kpc-in{width:100%;height:52px;padding:0 44px 0 14px;border:1.5px solid var(--kpc-line);border-radius:12px;background:#f8f9fc;
      font-size:18px;font-weight:600;color:var(--kpc-text);outline:none;transition:border-color .2s,background .2s,box-shadow .2s;-webkit-appearance:none;appearance:none}
    .kpc .kpc-in::placeholder{color:#b3b9c6;font-weight:500}
    .kpc .kpc-in:focus{border-color:var(--kpc-accent);background:#fff;box-shadow:0 0 0 4px rgba(59,110,245,.12)}
    .kpc .kpc-in.kpc-bad{border-color:var(--kpc-bad)}
    .kpc .kpc-unit{position:absolute;right:12px;top:50%;transform:translateY(-50%);font-size:14px;color:var(--kpc-sub);pointer-events:none}
    .kpc .kpc-hint{margin-top:6px;font-size:12.5px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-hint b{color:var(--kpc-accent)}
    .kpc .kpc-chips{display:grid;grid-template-columns:1fr 1fr;gap:6px}
    .kpc .kpc-chips.kpc-5{grid-template-columns:repeat(5,1fr);margin-top:8px}
    .kpc .kpc-chip{min-height:40px;padding:4px 6px;border:1.5px solid var(--kpc-line);border-radius:999px;background:#fff;color:var(--kpc-sub);
      font-size:13.5px;font-weight:600;line-height:1.3;cursor:pointer;word-break:keep-all;transition:all .2s}
    .kpc .kpc-chips.kpc-5 .kpc-chip{min-height:34px;font-size:13px;white-space:nowrap}
    .kpc .kpc-chip:hover{border-color:#c9d3ea;color:var(--kpc-text)}
    .kpc .kpc-chip.kpc-on{border-color:var(--kpc-accent);background:var(--kpc-accent-soft);color:var(--kpc-accent)}
    .kpc .kpc-chip small{display:block;font-size:11.5px;font-weight:500}
    .kpc .kpc-msg{min-height:20px;margin-top:12px;font-size:13px;color:var(--kpc-bad);word-break:keep-all}
    .kpc .kpc-result{display:grid;grid-template-rows:0fr;opacity:0;transform:translateY(8px);
      transition:grid-template-rows .35s ease,opacity .35s ease,transform .35s ease}
    .kpc .kpc-result.kpc-show{grid-template-rows:1fr;opacity:1;transform:none}
    .kpc .kpc-result-inner{overflow:hidden}
    .kpc .kpc-main{margin-top:4px;padding:22px 20px;border-radius:16px;background:var(--kpc-accent-soft);text-align:center}
    .kpc .kpc-main-label{font-size:14px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-big{margin-top:2px;font-size:36px;font-weight:800;letter-spacing:-.03em;color:var(--kpc-accent);line-height:1.25;word-break:keep-all}
    .kpc .kpc-big small{font-size:20px;font-weight:700;margin-left:2px}
    .kpc .kpc-sub{margin-top:6px;font-size:14px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-badge{display:inline-block;margin-top:8px;padding:3px 10px;border-radius:999px;background:#fff;font-size:13px;font-weight:700;color:var(--kpc-accent)}
    .kpc .kpc-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}
    .kpc .kpc-card{padding:14px;border:1px solid var(--kpc-line);border-radius:14px;background:#fff}
    .kpc .kpc-card-k{font-size:12px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-card-v{margin-top:2px;font-size:17px;font-weight:700;color:var(--kpc-text);word-break:keep-all}
    .kpc .kpc-card-v.kpc-down{color:var(--kpc-bad)}
    .kpc .kpc-card-v.kpc-up{color:var(--kpc-accent)}
    .kpc .kpc-card-s{margin-top:2px;font-size:12px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-tip{margin-top:8px;padding:12px 14px;border-radius:12px;background:#f8f9fc;font-size:13.5px;word-break:keep-all}
    .kpc .kpc-tip b{color:var(--kpc-accent)}
    .kpc .kpc-tbl-k{margin-top:16px;font-size:13px;font-weight:700}
    .kpc .kpc-table{width:100%;margin-top:6px;border:1px solid var(--kpc-line);border-radius:14px;border-collapse:separate;border-spacing:0;overflow:hidden;font-size:13px}
    .kpc .kpc-table th,.kpc .kpc-table td{padding:8px 8px;border:0;border-bottom:1px solid var(--kpc-line);background:#fff;text-align:center;color:var(--kpc-text);white-space:nowrap}
    .kpc .kpc-table thead th{background:#f8f9fc;font-size:12px;font-weight:600;color:var(--kpc-sub)}
    .kpc .kpc-table tbody th{font-weight:600}
    .kpc .kpc-table tr:last-child th,.kpc .kpc-table tr:last-child td{border-bottom:0}
    .kpc .kpc-table tr.kpc-sel th,.kpc .kpc-table tr.kpc-sel td{background:var(--kpc-accent-soft);color:var(--kpc-accent);font-weight:700}
    .kpc .kpc-note{margin-top:12px;font-size:12.5px;color:var(--kpc-sub);word-break:keep-all}
    .kpc .kpc-note li{margin-left:16px}
    .kpc .kpc-note li+li{margin-top:2px}
    .kpc .kpc-nowrap{white-space:nowrap}
    .kpc .kpc-actions{display:flex;gap:8px;margin-top:14px}
    .kpc .kpc-btn{flex:1;height:44px;border:1.5px solid var(--kpc-line);border-radius:12px;background:#fff;color:var(--kpc-text);
      font-size:14px;font-weight:600;cursor:pointer;transition:background .2s,transform .1s}
    .kpc .kpc-btn:hover{background:#f4f6fa}
    .kpc .kpc-btn:active{transform:scale(.98)}
    .kpc .kpc-btn.kpc-primary{border-color:var(--kpc-accent);background:var(--kpc-accent);color:#fff}
    .kpc .kpc-btn.kpc-primary:hover{background:#2f5fe0}
    @media (max-width:420px){.kpc{padding:18px;border-radius:16px}.kpc .kpc-big{font-size:31px}.kpc .kpc-in{font-size:17px}
      .kpc .kpc-chip{font-size:13px}.kpc .kpc-chips.kpc-5 .kpc-chip{font-size:12px;padding:4px 2px}
      .kpc .kpc-table{font-size:12.5px}.kpc .kpc-table th,.kpc .kpc-table td{padding:8px 4px}}
    @media (prefers-reduced-motion:reduce){.kpc .kpc-result,.kpc .kpc-in,.kpc .kpc-btn,.kpc .kpc-chip{transition:none}}
  </style>

  <p class="kpc-title">국민연금 추납 보험료 계산기</p>
  <p class="kpc-desc">기준소득월액과 추납 개월 수를 넣으면 총 추납액, 분할 납부 월액, 2026년·2027년 보험료율 차이를 바로 보여 줘요.</p>

  <label class="kpc-label" for="kpc-inc">지금 기준소득월액 <small>월 소득</small></label>
  <div class="kpc-field"><input class="kpc-in" id="kpc-inc" data-inc inputmode="numeric" maxlength="11" placeholder="2,000,000" aria-label="기준소득월액(원)"><span class="kpc-unit">원</span></div>
  <p class="kpc-hint">직장인은 비과세를 뺀 월급, 지역가입자는 신고한 월 소득이에요. 추납은 <b>신청한 달</b>의 기준소득월액으로 계산해요.</p>

  <label class="kpc-label" for="kpc-mon">추납할 개월 수 <small>최대 119개월</small></label>
  <div class="kpc-field"><input class="kpc-in" id="kpc-mon" data-mon inputmode="numeric" maxlength="3" placeholder="60" aria-label="추납 개월 수"><span class="kpc-unit">개월</span></div>

  <p class="kpc-label">지금 가입 종류</p>
  <div class="kpc-chips" data-group="type">
    <button type="button" class="kpc-chip kpc-on" data-type="0">사업장·지역가입자</button>
    <button type="button" class="kpc-chip" data-type="1">임의가입자<small>전업주부 등</small></button>
  </div>

  <p class="kpc-label">언제 낼 건가요? <small>보험료율</small></p>
  <div class="kpc-chips" data-group="year">
    <button type="button" class="kpc-chip" data-year="2026">2026년 적용<small>9.5%</small></button>
    <button type="button" class="kpc-chip" data-year="2027">2027년 적용<small>10%</small></button>
  </div>
  <p class="kpc-hint" data-timing></p>

  <label class="kpc-label" for="kpc-div">나눠 낼 횟수 <small>비우면 일시납</small></label>
  <div class="kpc-field"><input class="kpc-in" id="kpc-div" data-div inputmode="numeric" maxlength="2" placeholder="1" aria-label="분할 납부 횟수"><span class="kpc-unit">회</span></div>
  <div class="kpc-chips kpc-5">
    <button type="button" class="kpc-chip" data-n="1">일시납</button><button type="button" class="kpc-chip" data-n="12">12회</button><button type="button" class="kpc-chip" data-n="24">24회</button><button type="button" class="kpc-chip" data-n="36">36회</button><button type="button" class="kpc-chip" data-n="60">60회</button>
  </div>

  <p class="kpc-msg" data-msg role="status" aria-live="polite"></p>

  <div class="kpc-result" data-result aria-live="polite">
    <div class="kpc-result-inner">
      <div class="kpc-main">
        <p class="kpc-main-label" data-main-label></p>
        <p class="kpc-big"><span data-total>0</span><small>원</small></p>
        <p class="kpc-sub" data-main-sub></p>
        <span class="kpc-badge" data-period></span>
      </div>
      <div class="kpc-grid">
        <div class="kpc-card"><p class="kpc-card-k">1개월분 추납 보험료</p><p class="kpc-card-v" data-month></p><p class="kpc-card-s" data-month-s></p></div>
        <div class="kpc-card"><p class="kpc-card-k">분할 시 한 번에 내는 돈</p><p class="kpc-card-v" data-inst></p><p class="kpc-card-s" data-inst-s></p></div>
        <div class="kpc-card"><p class="kpc-card-k">2026년 vs 2027년 차액</p><p class="kpc-card-v kpc-down" data-diff></p><p class="kpc-card-s">2027년에 내면 이만큼 더 내요</p></div>
        <div class="kpc-card"><p class="kpc-card-k">늘어나는 가입기간</p><p class="kpc-card-v kpc-up" data-plus></p><p class="kpc-card-s" data-plus-s></p></div>
      </div>
      <p class="kpc-tip" data-tip></p>
      <p class="kpc-tbl-k">보험료율별 비교</p>
      <table class="kpc-table">
        <thead><tr><th scope="col">내는 시점</th><th scope="col">보험료율</th><th scope="col">1개월분</th><th scope="col">총 추납액</th></tr></thead>
        <tbody data-tbody></tbody>
      </table>
      <ul class="kpc-note">
        <li>보험료율은 <b>납부기한이 속한 달</b> 기준이에요(<span class="kpc-nowrap">2025. 11. 25.</span> 개정). 납부기한은 보통 신청한 다음 달 말일이라, 12월에 신청하면 12월 안에 내야 그해 보험료율이 적용돼요.</li>
        <li>분할 납부는 최대 60회(60개월 미만 신청은 그 개월 수까지)이고, 1년 만기 정기예금 이자율로 분할 이자가 붙어요. 위 금액은 이자를 뺀 원금이에요.</li>
        <li>늘어나는 연금액은 개인마다 달라서 계산하지 않아요. 국민연금공단 ‘내 연금 알아보기’나 상담(국번 없이 1355)에서 확인하세요.</li>
        <li>공단 고지액과 끝자리가 조금 다를 수 있어요. 추납 가능 기간과 정확한 금액은 공단에서 확인한 뒤 신청하세요.</li>
      </ul>
      <div class="kpc-actions">
        <button type="button" class="kpc-btn" data-reset>다시 입력</button>
        <button type="button" class="kpc-btn kpc-primary" data-copy>결과 복사</button>
      </div>
    </div>
  </div>

  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-kpc]');
    if (!root || root.__kpc) return;
    root.__kpc = true;

    // 국민연금법 제88조(2025. 3. 개정): 보험료율 2026년 9.5%, 2027년 10% (천분율)
    var RATE = { 2026: 95, 2027: 100 };
    // 기준소득월액 하한·상한 (보건복지부고시 제2026-31호, 2026. 7. 1. ~ 2027. 6. 30.)
    var MIN_BASE = 410000, MAX_BASE = 6590000;
    // 임의가입자 추납 상한: 전체 가입자 평균소득월액(A값) 2026년 3,193,511원
    var A_VALUE = 3193511;
    var MAX_MONTHS = 119;   // 2020. 12. 29. 이후 신청분: 119개월 초과 불가
    var MAX_DIV = 60;       // 분할 최대 60회

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var incI = $('[data-inc]'), monI = $('[data-mon]'), divI = $('[data-div]');
    var msg = $('[data-msg]'), result = $('[data-result]');
    var type = 0, lastText = '';

    function today() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
    function comma(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function won(n) { return comma(n) + '원'; }
    function rateText(r) { return (r / 10).toFixed(1).replace(/\.0$/, '') + '%'; }
    function periodText(m) { var y = Math.floor(m / 12), r = m % 12; return (y ? y + '년' : '') + (y && r ? ' ' : '') + (r ? r + '개월' : ''); }

    var now = today();
    var year = now.getFullYear() >= 2027 ? 2027 : 2026;

    function timingText() {
      var y = now.getFullYear(), m = now.getMonth() + 1;
      if (y < 2026 || (y === 2026 && m <= 11)) return '<span class="kpc-nowrap">2026. 11. 30.</span>까지 신청하면 납부기한이 12월이라 <b>9.5%</b>예요. 12월에 신청하면 <b>12월 안에 납부까지</b> 마쳐야 9.5%이고, 2027년 1월에 내면 10%예요.';
      if (y === 2026 && m === 12) return '12월에 신청했다면 <b><span class="kpc-nowrap">2026. 12. 31.</span>까지 납부</b>해야 9.5%예요(부칙 특례). 2027년 1월에 내면 10%가 적용돼요.';
      return '2027년에 내는 추납 보험료는 <b>10%</b>예요. 2026년 9.5% 칩은 비교용으로 보세요.';
    }

    function setChips(attr, val) { $$('[' + attr + ']').forEach(function (c) { c.classList.toggle('kpc-on', c.getAttribute(attr) === String(val)); }); }

    function hide(text) { result.classList.remove('kpc-show'); msg.textContent = text || ''; }

    function monthly(base, r) { return Math.floor(base * r / 1000 / 10) * 10; } // 10원 미만 버림

    function calc() {
      [incI, monI, divI].forEach(function (i) { i.classList.remove('kpc-bad'); });
      setChips('data-n', divI.value ? +divI.value : 1);
      var incRaw = incI.value.replace(/\D/g, ''), monRaw = monI.value, divRaw = divI.value;
      if (!incRaw || !monRaw) return hide('');
      var inc = +incRaw, mon = +monRaw, div = divRaw ? +divRaw : 1;
      if (inc < 1) { incI.classList.add('kpc-bad'); return hide('기준소득월액을 1원 이상으로 넣어 주세요.'); }
      if (mon < 1) { monI.classList.add('kpc-bad'); return hide('추납 개월 수는 1개월 이상이어야 해요.'); }
      if (mon > MAX_MONTHS) { monI.classList.add('kpc-bad'); return hide('추납은 최대 119개월(10년 미만)까지만 신청할 수 있어요.'); }
      if (div < 1) { divI.classList.add('kpc-bad'); return hide('나눠 낼 횟수는 1회(일시납) 이상이어야 해요.'); }
      if (div > MAX_DIV) { divI.classList.add('kpc-bad'); return hide('분할 납부는 최대 60회까지예요.'); }
      if (div > mon) { divI.classList.add('kpc-bad'); return hide('60개월 미만으로 신청하면 신청한 개월 수(' + mon + '회)까지만 나눌 수 있어요.'); }

      var base = Math.floor(inc / 1000) * 1000, baseNote = '천원 미만 버림';
      if (base < MIN_BASE) { base = MIN_BASE; baseNote = '하한 41만원 적용'; }
      else if (base > MAX_BASE) { base = MAX_BASE; baseNote = '상한 659만원 적용'; }
      if (type === 1 && base > A_VALUE) { base = A_VALUE; baseNote = '임의가입자 상한(A값) 적용'; }

      var rows = [2026, 2027].map(function (y) { var m = monthly(base, RATE[y]); return { y: y, r: RATE[y], m: m, t: m * mon }; });
      var sel = rows[year === 2026 ? 0 : 1], other = rows[year === 2026 ? 1 : 0];
      var diff = rows[1].t - rows[0].t;
      var inst = Math.floor(sel.t / div);

      msg.textContent = '';
      $('[data-main-label]').textContent = '총 추납 보험료 (' + sel.y + '년 ' + rateText(sel.r) + ' 적용)';
      $('[data-total]').textContent = comma(sel.t);
