      <div class="ksd-formula" data-formula></div>

      <ul class="ksd-note">
        <li>은행연합회 ‘2026년 하반기 스트레스 DSR 운영방안’(2026. 7. 1.~12. 31.) 기준이에요. 2027년 1월부터 쓸 스트레스 금리와 지방 완화 연장 여부는 12월에 발표될 예정이라 아직 반영하지 못했어요.</li>
        <li>실제 한도는 은행 심사로 정해져요. 소득 인정 방식, 기존 대출 산정, 금리, 은행별 내부 기준, 다주택 여부(수도권·규제지역 다주택자는 구입 목적 주담대 불가)에 따라 달라질 수 있어요.</li>
        <li>특정 금융상품을 권하는 내용이 아니며, 정확한 한도는 대출받을 금융회사에 확인해 주세요.</li>
      </ul>
      <div class="ksd-actions">
        <button type="button" class="ksd-btn" data-reset>다시 입력</button>
        <button type="button" class="ksd-btn ksd-primary" data-copy>결과 복사</button>
      </div>
    </div>
  </div>

  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-ksd]');
    if (!root || root.__ksd) return;
    root.__ksd = true;

    // ===== 규제 기준값 (README.md "매년 할 일" 참고, 2026. 7. 1.~12. 31. 적용) =====
    // 스트레스 금리(%p) = 기준 스트레스 금리 × 기본 적용비율 × 금리유형별 반영비율
    // 혼합형·주기형 반영비율은 고정기간 [5~9년, 9~15년, 15~21년, 21년 이상] (만기 30년 기준)
    var STRESS = {
      // 수도권·규제지역 주담대: 10·15 대책 3.0%, 3단계 기본 적용비율 100%, 3단계 유형별 비율
      metro: { base: 3.0, ratio: 1.0, mix: [.8, .6, .4, 0], cyc: [.4, .3, .2, 0], stage: '3단계(10·15 대책 3.0%)' },
      // 지방(비규제) 주담대: 2026. 12. 31.까지 2단계 유지 → 1.5% × 50%, 2단계 유형별 비율
      local: { base: 1.5, ratio: .5, mix: [.6, .4, .2, 0], cyc: [.3, .2, .1, 0], stage: '2단계 유지(1.5% × 50%)' },
      // 비교용: 지방에도 3단계가 적용되면
      local3: { base: 1.5, ratio: 1.0, mix: [.8, .6, .4, 0], cyc: [.4, .3, .2, 0], stage: '3단계(1.5%)' }
    };
    var CREDIT_STRESS = 1.5, CREDIT_STRESS_OVER = 10000; // 신용대출 잔액 1억 원(만원 단위) 초과 시 1.5%p
    var CREDIT_YEARS = 5;                                  // DSR 산정 시 신용대출 만기 5년 가정
    var DSR = { bank: .4, nonbank: .5 };
    var MAX_YEARS_METRO = 30;                              // 6·27 대책: 수도권·규제지역 주담대 만기 30년 이내
    // LTV(무주택·처분조건 1주택, 구입 목적): [일반, 생애최초]
    var LTV = { reg: [.4, .7], metro: [.7, .7], local: [.7, .8] };
    // 수도권·규제지역 구입 목적 주담대 한도(10·15 대책): 시가 15억 이하 6억, 25억 이하 4억, 초과 2억 (만원)
    var CAPS = [[150000, 60000], [250000, 40000], [Infinity, 20000]];
    // ===== 기준값 끝 =====

    // ENGINE START
    function stressOf(set, type, fixp) {
      var f = type === 'var' ? 1 : type === 'fix' ? 0 : set[type][fixp];
      return Math.round(set.base * set.ratio * f * 1000) / 1000;
    }
    // 연간 원리금 A(만원)로 갚을 수 있는 원금(만원), 원리금균등, 월 단위
    function principal(A, ratePct, years) {
      var r = ratePct / 100 / 12, n = years * 12, m = A / 12;
      if (A <= 0) return 0;
      if (r === 0) return m * n;
      return m * (1 - Math.pow(1 + r, -n)) / r;
    }
    function annualPay(P, ratePct, years) {
      var r = ratePct / 100 / 12, n = years * 12;
      if (r === 0) return P / n * 12;
      return P * r / (1 - Math.pow(1 + r, -n)) * 12;
    }
    // o: { inc, region, sector, type, fixp, rate, yrs, ext, cr, crr, price, first, want } (금액은 만원)
    function compute(o) {
      var set = o.region === 'local' ? STRESS.local : STRESS.metro;
      var st = stressOf(set, o.type, o.fixp);
      var dsrRate = o.rate + st;
      var crStress = o.cr > CREDIT_STRESS_OVER ? CREDIT_STRESS : 0;
      var crAnnual = o.cr > 0 ? o.cr / CREDIT_YEARS + o.cr * (o.crr + crStress) / 100 : 0;
      var existing = o.ext + crAnnual;
      var lim = o.inc * DSR[o.sector];
      var room = lim - existing;
      var max = Math.max(Math.floor(principal(room, dsrRate, o.yrs)), 0);
      var noStress = Math.max(Math.floor(principal(room, o.rate, o.yrs)), 0);
      var local3 = null;
      if (o.region === 'local') {
        var st3 = stressOf(STRESS.local3, o.type, o.fixp);
        local3 = { st: st3, max: Math.max(Math.floor(principal(room, o.rate + st3, o.yrs)), 0) };
      }
      var ltv = null, cap = null, final = max, bind = 'dsr';
      if (o.price > 0) {
        var lr = LTV[o.region][o.first ? 1 : 0];
        ltv = { rate: lr, amt: Math.floor(o.price * lr + 1e-6) };
        if (o.region !== 'local') for (var i = 0; i < CAPS.length; i++) if (o.price <= CAPS[i][0]) { cap = CAPS[i][1]; break; }
        if (ltv.amt < final) { final = ltv.amt; bind = 'ltv'; }
        if (cap !== null && cap < final) { final = cap; bind = 'cap'; }
      }
      var month = final > 0 ? annualPay(final, o.rate, o.yrs) / 12 : 0;
      var want = null;
      if (o.want > 0) {
        var wa = annualPay(o.want, dsrRate, o.yrs);
        want = { annual: wa, dsr: (existing + wa) / o.inc * 100 };
      }
      return { set: set, st: st, dsrRate: dsrRate, crStress: crStress, crAnnual: crAnnual, existing: existing, lim: lim, room: room,
        max: max, noStress: noStress, local3: local3, ltv: ltv, cap: cap, final: final, bind: bind, month: month, want: want };
    }
    // ENGINE END

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var incI = $('[data-inc]'), rateI = $('[data-rate]'), yrsI = $('[data-yrs]'), extI = $('[data-ext]'), crI = $('[data-cr]'), crrI = $('[data-crr]'),
      priceI = $('[data-price]'), wantI = $('[data-want]');
    var msg = $('[data-msg]'), result = $('[data-result]'), incRead = $('[data-inc-read]'), priceRead = $('[data-price-read]');
    var INC_HINT = incRead.textContent, PRICE_HINT = priceRead.textContent, lastText = '';
    var st = { region: 'reg', sector: 'bank', type: 'var', fixp: 0, first: false, more: false };
    var REGION_NAME = { reg: '규제지역', metro: '수도권(비규제)', local: '지방(비규제)' };
    var TYPE_NAME = { 'var': '변동형', mix: '혼합형', cyc: '주기형', fix: '순수 고정형' };
    var FIXP_NAME = ['5~9년', '9~15년', '15~21년', '21년 이상'];
    var REGION_HINT = {
      reg: '투기과열지구·조정대상지역(2025. 10. 16. 기준 서울 전역과 경기 12곳)이에요. 스트레스 금리 3.0%, LTV 40%, 만기 30년 이내가 적용돼요.',
      metro: '규제지역이 아닌 경기·인천도 수도권이라 스트레스 금리 3.0%와 주택가격별 한도(최대 6억 원)가 적용돼요. LTV는 70%예요.',
      local: '서울·경기·인천 밖 비규제지역이에요. 2026년 말까지는 완화된 2단계 스트레스 금리(0.75%)가 적용돼요.'
    };

    function comma(n) { return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function digits(s) { return String(s).replace(/\D/g, ''); }
    function num(s) { var v = String(s).replace(/[^\d.]/g, ''); return v === '' || isNaN(+v) ? NaN : +v; }
    // 만원 → "3억 5,120만 원"
    function man(n) {
      n = Math.floor(n);
      var eok = Math.floor(n / 1e4), m = n % 1e4, out = [];
      if (eok) out.push(comma(eok) + '억');
      if (m) out.push(comma(m) + '만');
      return (out.join(' ') || '0') + ' 원';
    }
    function manWon(n) { return comma(Math.round(n)) + '만 원'; }
    function dec(x) { var t = Math.round(x * 1000); return (t % 10 ? t / 1000 : t / 1000).toFixed(t % 10 ? 3 : 2); }
    function pctp(x) { return dec(x) + '%p'; }
    function pct(x) { return dec(x) + '%'; }
    function ratio(x) { return Math.round(x * 100) + '%'; }

    [[3000, '3천'], [4000, '4천'], [5000, '5천'], [6000, '6천'], [8000, '8천'], [10000, '1억']].forEach(function (c) {
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'ksd-chip'; b.dataset.v = c[0]; b.textContent = c[1] + '만 원';
      b.addEventListener('click', function () { incI.value = comma(c[0]); calc(); });
      $('[data-inc-chips]').appendChild(b);
    });

    function press(attr, val) {
      $$('[' + attr + ']').forEach(function (b) { var on = b.getAttribute(attr) === String(val); b.classList.toggle('ksd-on', on); b.setAttribute('aria-pressed', on); });
    }
    function sync() {
      press('data-region', st.region); press('data-sector', st.sector); press('data-type', st.type);
      press('data-fixp', st.fixp); press('data-first', st.first ? 1 : 0);
      $('[data-fixp-box]').hidden = !(st.type === 'mix' || st.type === 'cyc');
      $('[data-region-hint]').textContent = REGION_HINT[st.region];
      $('[data-more-box]').hidden = !st.more;
      $('[data-more]').setAttribute('aria-expanded', st.more);
      $('[data-more]').textContent = (st.more ? '− ' : '+ ') + '기존 대출·집값 넣기 (선택)';
    }

    function hide(text, bad) {
      result.classList.remove('ksd-show');
      msg.textContent = text || '';
      $$('.ksd-in').forEach(function (i) { i.classList.toggle('ksd-bad', !!bad && bad.indexOf(i) >= 0); });
    }

    function money(input, max, name) {
      // 빈칸 = 0, 숫자만, 상한 확인
      var d = digits(input.value);
      if (d.length > 9 || +d > max) return { err: name + ' 금액이 너무 커요. 만원 단위로 넣었는지 확인해 주세요.' };
      return { v: +d };
    }

    function calc() {
      sync();
      var inc = +digits(incI.value);
      $$('.ksd-chip').forEach(function (c) { c.classList.toggle('ksd-on', +c.dataset.v === inc && !!incI.value); });
      incRead.textContent = inc ? '= ' + man(inc) : INC_HINT;
      var price = +digits(priceI.value);
      priceRead.textContent = price ? '= ' + man(price) + ' · ' + PRICE_HINT : PRICE_HINT;

      if (!incI.value) return hide('');
      if (digits(incI.value).length > 7) return hide('연소득이 너무 커요. 만원 단위로 넣었는지 확인해 주세요.', [incI]);
      if (inc < 100) return hide('연소득을 만원 단위로 100만 원 이상 넣어 주세요.', [incI]);
      if (!rateI.value.trim()) return hide('대출 금리를 넣어 주세요.', [rateI]);
      var rate = num(rateI.value);
      if (isNaN(rate) || rate <= 0 || rate > 20) return hide('대출 금리는 0%보다 크고 20% 이하로 넣어 주세요.', [rateI]);
      if (!yrsI.value.trim()) return hide('대출 기간을 넣어 주세요.', [yrsI]);
      var yrs = +digits(yrsI.value);
      if (!yrs || yrs > 50) return hide('대출 기간은 1년부터 50년까지 넣어 주세요.', [yrsI]);
      if (st.region !== 'local' && yrs > MAX_YEARS_METRO) return hide('수도권·규제지역 주담대는 만기를 30년 이내로만 받을 수 있어요(2025. 6. 28.부터).', [yrsI]);

      var ext = 0, cr = 0, crr = 0, want = 0;
      if (st.more) {
        var e = money(extI, 9999999, '기존 대출 원리금'); if (e.err) return hide(e.err, [extI]); ext = e.v;
        var c = money(crI, 9999999, '신용대출 잔액'); if (c.err) return hide(c.err, [crI]); cr = c.v;
        if (cr > 0) {
          if (!crrI.value.trim()) return hide('신용대출 금리를 넣어 주세요.', [crrI]);
          crr = num(crrI.value);
          if (isNaN(crr) || crr < 0 || crr > 20) return hide('신용대출 금리는 0~20% 사이로 넣어 주세요.', [crrI]);
        }
        var p = money(priceI, 99999999, '집값'); if (p.err) return hide(p.err, [priceI]);
        if (priceI.value && p.v < 100) return hide('집값을 만원 단위로 넣어 주세요(예: 9억 원 → 90,000).', [priceI]);
        var w = money(wantI, 9999999, '받고 싶은'); if (w.err) return hide(w.err, [wantI]); want = w.v;
      } else price = 0;

      var o = { inc: inc, region: st.region, sector: st.sector, type: st.type, fixp: st.fixp, rate: rate, yrs: yrs,
        ext: ext, cr: cr, crr: crr, price: price, first: st.first, want: want };
      var r = compute(o);
      hide('');

      var noRoom = r.room <= 0;
      $('[data-big-label]').textContent = price ? '받을 수 있는 최대 주담대 (DSR·LTV·한도 중 작은 값)' : '주담대 최대 한도 (DSR 기준)';
      $('[data-big]').innerHTML = noRoom ? '0<small>원</small>' : man(r.final).replace(/ 원$/, '') + '<small>원</small>';
      $('[data-sub]').innerHTML = '<span class="ksd-nw">' + REGION_NAME[st.region] + '</span> · <span class="ksd-nw">' +
        (st.sector === 'bank' ? '은행' : '2금융권') + ' DSR ' + ratio(DSR[st.sector]) + '</span> · <span class="ksd-nw">' + TYPE_NAME[st.type] +
        (st.type === 'mix' || st.type === 'cyc' ? '(' + FIXP_NAME[st.fixp] + ')' : '') + '</span> · <span class="ksd-nw">' + yrs + '년</span>';

      $('[data-c-stress]').textContent = '+' + pctp(r.st);
      $('[data-c-dsrrate]').textContent = pct(r.dsrRate);
      $('[data-c-nostress]').textContent = noRoom ? '0원' : man(r.noStress);
      $('[data-c-month]').textContent = r.final > 0 ? '월 ' + manWon(r.month) : '-';

      var capEl = $('[data-cap]');
      capEl.classList.remove('ksd-warn');
      if (noRoom) {
        capEl.classList.add('ksd-warn');
        capEl.innerHTML = '기존 대출 원리금이 이미 연소득의 ' + ratio(DSR[st.sector]) + '(' + manWon(r.lim) + ')를 넘어 <b>새 주담대를 받을 DSR 여유가 없어요.</b> 기존 대출을 줄이거나 갚으면 한도가 생겨요.';
      } else {
        var lost = r.noStress - r.max;
        var t = lost > 0 ? '스트레스 금리 ' + pctp(r.st) + ' 때문에 한도가 <b>' + man(lost) + '</b> 줄었어요.' : '이 조건은 스트레스 금리가 붙지 않아 <b>한도가 줄지 않아요.</b>';
        if (r.ltv) {
          t += ' DSR 기준 ' + man(r.max) + ', LTV ' + ratio(r.ltv.rate) + ' 기준 ' + man(r.ltv.amt) +
            (r.cap !== null ? ', 주택가격별 한도 ' + man(r.cap) : '') + ' 중 가장 작은 <b>' + { dsr: 'DSR', ltv: 'LTV', cap: '주택가격별 한도' }[r.bind] + '</b> 기준이 적용돼요.' +
            (r.cap === null ? ' 지방(비규제)은 주택가격별 한도가 없어요.' : '');
        }
        capEl.innerHTML = t;
      }

      var wi = $('[data-want-info]');
      wi.hidden = !r.want;
      wi.classList.remove('ksd-warn');
      if (r.want) {
        var ok = r.want.dsr <= DSR[st.sector] * 100 + 1e-9;
        var okLtv = !r.ltv || (want <= r.ltv.amt && (r.cap === null || want <= r.cap));
        wi.classList.toggle('ksd-warn', !(ok && okLtv));
        wi.innerHTML = man(want) + '을 받으면 스트레스 DSR은 <b>' + (Math.round(r.want.dsr * 10) / 10).toFixed(1) + '%</b>예요(한도 ' + ratio(DSR[st.sector]) + '). ' +
          (ok ? (okLtv ? 'DSR·LTV 기준 안에 들어와요.' : 'DSR은 괜찮지만 <b>LTV나 주택가격별 한도를 넘어요.</b>') : '<b>DSR 한도를 넘어요.</b>');
      }

      var li = $('[data-local-info]');
      li.hidden = !r.local3 || noRoom;
      if (r.local3 && !noRoom) {
        li.innerHTML = '지방 주담대 완화(2단계)는 <span class="ksd-nw">2026. 12. 31.</span>까지예요. 2027년에 지방에도 3단계(스트레스 ' + pctp(r.local3.st) + ')가 적용되면 DSR 한도는 <b>' + man(r.local3.max) + '</b>까지 줄어요(12월 발표 전, 참고용).';
      }

      var set = function (k, v) { root.querySelector('[data-r="' + k + '"]').textContent = v; };
      set('limlab', manWon(inc) + ' × ' + ratio(DSR[st.sector]));
      set('lim', manWon(r.lim));
      set('extlab', cr > 0 ? '입력 ' + manWon(ext) + ' + 신용대출 ' + manWon(r.crAnnual) + (r.crStress ? ' (1억 초과, 금리 +1.5%p)' : '') : '입력한 값');
      set('ext', '−' + manWon(r.existing));
      set('room', noRoom ? '0만 원' : manWon(r.room));
      var stLab = r.set.stage + ', ' + TYPE_NAME[st.type] + (st.type === 'mix' || st.type === 'cyc' ? ' ' + FIXP_NAME[st.fixp] : '');
      set('ratelab', rate + '% + 스트레스 ' + pctp(r.st) + ' (' + stLab + ')');
      set('rate', pct(r.dsrRate));
      set('max', noRoom ? '0원' : man(r.max));

      var f = [];
      var factor = st.type === 'var' ? 1 : st.type === 'fix' ? 0 : r.set[st.type][st.fixp];
      f.push('스트레스 금리 = ' + r.set.base.toFixed(1) + '% × 기본 ' + ratio(r.set.ratio) + ' × ' + TYPE_NAME[st.type] + ' ' + ratio(factor) + ' = <b>' + pctp(r.st) + '</b>');
      f.push('연간 원리금 여유 = ' + manWon(r.lim) + ' − ' + manWon(r.existing) + ' = ' + (noRoom ? '0만 원' : manWon(r.room)));
      if (!noRoom) f.push('최대 대출 = 월 ' + manWon(r.room / 12) + ' × (1 − (1 + ' + pct(r.dsrRate) + '÷12)<sup>−' + (yrs * 12) + '</sup>) ÷ (' + pct(r.dsrRate) + '÷12) = <b>' + man(r.max) + '</b>');
      $('[data-formula]').innerHTML = f.map(function (x) { return '<p>' + x + '</p>'; }).join('');
      result.classList.add('ksd-show');

