    var TAX_CAP = 1000;   // 만원, 연간 월세 공제 대상 한도 (2026년 지급분)
    // 주택 전월세 전환율 법정 상한 = 기준금리 + 2% (tools/rent-conversion-rate 의 BASE 와 같게)
    var LEGAL = { base: 3.25, add: 2, decided: '2026. 11. 26.' };
    var MONTHS = 24;      // 2년 계약
    var MAX = 9999999;    // 만원

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var m = {}, r = {};
    $$('[data-m]').forEach(function (i) { m[i.getAttribute('data-m')] = i; });
    $$('[data-r]').forEach(function (i) { r[i.getAttribute('data-r')] = i; });
    var msg = $('[data-msg]'), result = $('[data-result]');
    var tax = 0, lastText = '';

    function comma(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function num(s) { return s === '' ? NaN : +String(s).replace(/,/g, ''); }
    function man(v) {
      if (v <= 0) return '0원';
      var eok = Math.floor(v / 10000), rest = v % 10000;
      if (!eok) return comma(rest) + '만원';
      return comma(eok) + '억' + (rest ? ' ' + comma(rest) + '만원' : '원');
    }
    function won(w) { return (w < 0 ? '-' : '') + comma(Math.abs(w)) + '원'; }
    // 원 → "43만 7,500원"
    function wonK(w) {
      var neg = w < 0; w = Math.abs(w);
      var s;
      if (w < 10000) s = comma(w) + '원';
      else { var mm = Math.floor(w / 10000), rr = w % 10000; s = man(mm).replace(/원$/, '') + (rr ? ' ' + comma(rr) + '원' : '원'); }
      return (neg ? '-' : '') + s;
    }
    function pct(x) { return (Math.round(x * 100) / 100).toFixed(2) + '%'; }
    function pctS(x) { return String(+x) + '%'; }
    function josa(w, a, b) { var c = w.charCodeAt(w.length - 1) - 0xAC00; return c >= 0 && c < 11172 && c % 28 ? a : b; }

    function hide(text, bad) {
      result.classList.remove('kjw-show');
      msg.textContent = text || '';
      $$('.kjw-in').forEach(function (i) { i.classList.toggle('kjw-bad', !!bad && i === bad); });
    }

    function readAll() {
      var a = num(m.aDep.value), l = num(m.aLoan.value), bd = num(m.bDep.value), br = num(m.bRent.value);
      $('[data-read="aDep"]').innerHTML = a > 0 ? '= <b>' + man(a) + '</b>' : '만원 단위로 입력하세요. 3억원이면 30,000';
      $('[data-read="aLoan"]').textContent = l > 0 && a > 0 && l <= a ? '= 대출 ' + man(l) + ' + 내 돈 ' + man(a - l) : '대출이 없으면 0을 넣거나 비워 두세요.';
      $('[data-read="b"]').textContent = m.bDep.value !== '' || br > 0 ? '= 보증금 ' + (bd > 0 ? man(bd) : '없음') + ' / 월세 ' + (br > 0 ? man(br) : '-') : '금액은 모두 만원 단위예요. 월세 90만원이면 90';
      $('[data-tax-hint]').textContent = tax === 17 ? '총급여 5,500만원 이하(종합소득금액 4,500만원 이하)면 17%예요. 연 월세 1,000만원까지 공제돼요.'
        : tax === 15 ? '총급여 5,500만원 초과 8,000만원 이하(종합소득금액 7,000만원 이하)면 15%예요. 연 월세 1,000만원까지 공제돼요.'
        : '공제 요건을 갖췄다면 내 총급여에 맞는 공제율을 골라 보세요.';
    }

    function money(i, name, allowZero, empty0) {
      if (i.value === '') return empty0 ? 0 : null;
      var v = num(i.value);
      if (!(allowZero ? v >= 0 : v > 0)) return { err: name + josa(name, '을', '를') + (allowZero ? ' 0 이상으로' : ' 1만원 이상으로') + ' 입력해 주세요.', el: i };
      if (v > MAX) return { err: name + josa(name, '이', '가') + ' 너무 커요. 만원 단위로 입력했는지 확인해 주세요.', el: i };
      return v;
    }
    function rate(i, name, max, empty0) {
      if (i.value === '') return empty0 ? 0 : null;
      if (!/^\d{1,2}(\.\d{0,3})?$/.test(i.value) || +i.value > max) return { err: name + josa(name, '을', '를') + ' 0~' + max + '% 사이로 입력해 주세요.', el: i };
      return +i.value;
    }

    function calc() {
      readAll();
      var fields = [m.aDep, m.bDep, m.bRent, r.dr];
      if (fields.some(function (i) { return i.value === ''; })) {
        // 필수 칸이 비어 있으면 결과를 숨김. 이미 적은 칸에 오류가 있으면 그것부터 알려 줌
        var pre = [money(m.aDep, '전세 보증금'), money(m.aLoan, '전세대출', true, true), money(m.bDep, '월세 보증금', true), money(m.bRent, '월세'),
          rate(r.dr, '기회비용 금리', 20), rate(r.lr, '대출 금리', 20, true), rate(r.gr, '보증보험료율', 1, true)];
        for (var q = 0; q < pre.length; q++) if (pre[q] && pre[q].err) return hide(pre[q].err, pre[q].el);
        return hide(r.dr.value === '' && m.aDep.value !== '' && m.bRent.value !== '' ? '내 돈의 기회비용 금리(예금 금리)를 넣어 주세요. 예금을 안 한다면 0을 넣어도 돼요.' : '');
      }
      var aDep = money(m.aDep, '전세 보증금'), aLoan = money(m.aLoan, '전세대출', true, true),
          bDep = money(m.bDep, '월세 보증금', true), bRent = money(m.bRent, '월세'),
          dr = rate(r.dr, '기회비용 금리', 20), lr = rate(r.lr, '대출 금리', 20, true), gr = rate(r.gr, '보증보험료율', 1, true);
      var all = [aDep, aLoan, bDep, bRent, dr, lr, gr];
      for (var k = 0; k < all.length; k++) if (all[k] && all[k].err) return hide(all[k].err, all[k].el);
      if (aLoan > aDep) return hide('전세대출은 전세 보증금보다 클 수 없어요.', m.aLoan);
      if (aLoan > 0 && r.lr.value === '') return hide('전세대출 금리를 넣어 주세요.', r.lr);
      hide('');

      // A 전세: 대출이자 + 내 돈 기회비용 + 보증보험료 (원, 계산은 소수 그대로, 표시할 때만 반올림)
      var own = aDep - aLoan;
      var aInt = aLoan * 1e4 * lr / 1200;
      var aOpp = own * 1e4 * dr / 1200;
      var aGua = aDep * 1e4 * gr / 1200;
      var A = aInt + aOpp + aGua;
      // B 월세: 월세 + 보증금 기회비용 − 세액공제
      var rentW = bRent * 1e4;
      var bOpp = bDep * 1e4 * dr / 1200;
      var capW = TAX_CAP * 1e4;
      var credit = tax ? Math.min(bRent * 12 * 1e4, capW) * tax / 1200 : 0;
      var B = rentW + bOpp - credit;
      var R = Math.round, diff = R(A - B);

      var main = $('[data-main]');
      main.classList.toggle('kjw-wb', diff > 0);
      if (diff === 0) { $('[data-big]').textContent = '두 조건이 같아요'; $('[data-sub]').textContent = '한 달 실부담이 ' + wonK(R(A)) + '으로 같아요'; }
      else {
        $('[data-big]').textContent = (diff > 0 ? '월세' : '전세') + '가 월 ' + wonK(Math.abs(diff)) + ' 유리';
        $('[data-sub]').textContent = '2년이면 ' + wonK(R(Math.abs(A - B) * MONTHS)) + ' 차이예요';
      }
      $('[data-v="a"]').textContent = '월 ' + wonK(R(A));
      $('[data-s="a"]').textContent = '이자 ' + wonK(R(aInt)) + ' + 기회비용 ' + wonK(R(aOpp)) + (aGua ? ' + 보증료 ' + wonK(R(aGua)) : '');
      $('[data-v="b"]').textContent = '월 ' + wonK(R(B));
      $('[data-s="b"]').textContent = '월세 ' + wonK(rentW) + ' + 기회비용 ' + wonK(R(bOpp)) + (credit ? ' − 공제 ' + wonK(R(credit)) : '');
      $('[data-v="a2"]').textContent = wonK(R(A * MONTHS));
      $('[data-v="b2"]').textContent = wonK(R(B * MONTHS));

      // 손익분기 전환율: B 월세를 얼마로 하면 A와 같아지는지 → (그 월세 × 12) ÷ (A 보증금 − B 보증금)
      var legal = LEGAL.base + LEGAL.add, beLines = [], beTxt = '';
      var gap = (aDep - bDep) * 1e4;
      if (gap > 0) {
        var X = A - bOpp, t = tax / 100, Rstar;
        if (X <= 0) Rstar = 0;
        else if (!t) Rstar = X;
        else if (X <= capW / 12 * (1 - t)) Rstar = X / (1 - t);
        else Rstar = X + capW / 12 * t;
        var be = Rstar * 1200 / gap, cur = rentW * 1200 / gap;
        var beW = Math.round(Rstar);
        beTxt = '지금 월세 조건의 전환율은 <b>' + pct(cur) + '</b>, 두 조건이 같아지는 손익분기 전환율은 <b>' + pct(be) + '</b>예요. ';
        beTxt += Math.abs(cur - be) < 0.005 ? '거의 같아서 어느 쪽이든 비용 차이가 작아요. ' : (cur < be ? '전환율이 손익분기보다 낮아서 월세가 유리해요. ' : '전환율이 손익분기보다 높아서 전세가 유리해요. ');
        beTxt += beW > 0 ? '같은 보증금이라면 월세가 <span class="kjw-nowrap">월 ' + wonK(beW) + '</span>보다 적어야 월세가 유리해요. ' : '월세 보증금의 기회비용만으로도 전세 비용과 같거나 넘어서, 월세가 0원이어도 전세가 유리해요. ';
        beTxt += '참고로 계약 중·갱신 때 집주인이 받을 수 있는 법정 상한 전환율은 <span class="kjw-nowrap">' + pctS(legal) + '</span>(기준금리 ' + pctS(LEGAL.base) + ' + 2%)예요' +
          (be >= legal ? '. 손익분기가 이보다 높아서, 상한 안에서 바꾸면 계산상 월세 쪽이 유리해요.' : '. 손익분기가 이보다 낮아서, 상한까지 받는 조건이면 계산상 전세 쪽이 유리해요.');
        beLines = ['지금 전환율: ' + pct(cur), '손익분기 전환율: ' + pct(be) + ' (월세 ' + won(beW) + ')', '법정 상한 전환율: ' + pctS(legal)];
      } else {
        beTxt = '월세 보증금이 전세 보증금보다 작지 않아서 전환율은 계산하지 않았어요. 위의 월 실부담으로만 비교해 보세요.';
      }
      $('[data-be]').innerHTML = beTxt;

      var f = $('[data-formula]'); f.innerHTML = '';
      var lines = [
        ['h', 'A 전세 월 실부담'],
        ['', '대출이자 = ' + man(aLoan) + ' × ' + pctS(lr) + ' ÷ 12 = ' + won(R(aInt))],
        ['', '내 돈 기회비용 = ' + man(own) + ' × ' + pctS(dr) + ' ÷ 12 = ' + won(R(aOpp))]
      ];
      if (gr) lines.push(['', '보증보험료 = ' + man(aDep) + ' × ' + pctS(gr) + ' ÷ 12 = ' + won(R(aGua))]);
      lines.push(['h', 'B 월세 월 실부담']);
      lines.push(['', '월세 ' + won(rentW) + ' + 보증금 기회비용 ' + man(bDep) + ' × ' + pctS(dr) + ' ÷ 12 = ' + won(R(bOpp))]);
      if (tax) lines.push(['', '세액공제 = min(연 월세 ' + man(bRent * 12) + ', 1,000만원) × ' + tax + '% ÷ 12 = ' + won(R(credit))]);
      lines.forEach(function (l) { var p = document.createElement('p'); if (l[0]) p.className = 'kjw-fh'; p.textContent = l[1]; f.appendChild(p); });
      result.classList.add('kjw-show');

      lastText = '[전세 vs 월세 비교]\n' +
        'A 전세: 보증금 ' + man(aDep) + (aLoan ? ' (대출 ' + man(aLoan) + ', 금리 ' + pctS(lr) + ')' : '') + (gr ? ', 보증료율 ' + pctS(gr) : '') + '\n' +
        'B 월세: 보증금 ' + man(bDep) + ' / 월세 ' + man(bRent) + (tax ? ' (세액공제 ' + tax + '% 반영)' : '') + '\n' +
        '기회비용 금리: ' + pctS(dr) + '\n' +
        'A 월 실부담: ' + won(R(A)) + ' / 2년 ' + won(R(A * MONTHS)) + '\n' +
        'B 월 실부담: ' + won(R(B)) + ' / 2년 ' + won(R(B * MONTHS)) + '\n' +
        (diff === 0 ? '결과: 두 조건이 같아요' : '결과: ' + (diff > 0 ? '월세' : '전세') + '가 월 ' + won(Math.abs(diff)) + ' 유리 (2년 ' + won(R(Math.abs(A - B) * MONTHS)) + ')') +
        (beLines.length ? '\n' + beLines.join('\n') : '') + '\n※ 보증금 반환 위험은 계산에 넣지 않았어요';
    }

    Object.keys(m).forEach(function (key) {
      var i = m[key];
      i.addEventListener('input', function () {
        var v = i.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 7);
        i.value = v === '' ? '' : comma(v);
        calc();
      });
    });
    Object.keys(r).forEach(function (key) {
      var i = r[key];
      i.addEventListener('input', function () {
        var v = i.value.replace(/[^\d.]/g, ''), p = v.split('.');
        if (p.length > 1) v = p[0].slice(0, 2) + '.' + p.slice(1).join('').slice(0, 3); else v = v.slice(0, 2);
        i.value = v;
        calc();
      });
    });
    $$('[data-tax]').forEach(function (b) {
      b.addEventListener('click', function () {
        tax = +b.getAttribute('data-tax');
        $$('[data-tax]').forEach(function (c) { var on = c === b; c.classList.toggle('kjw-on', on); c.setAttribute('aria-checked', on); });
        calc();
      });
    });

    $('[data-reset]').addEventListener('click', function () {
      Object.keys(m).forEach(function (key) { m[key].value = ''; });
      Object.keys(r).forEach(function (key) { r[key].value = ''; });
      tax = 0;
      $$('[data-tax]').forEach(function (c) { var on = c.getAttribute('data-tax') === '0'; c.classList.toggle('kjw-on', on); c.setAttribute('aria-checked', on); });
      calc();
      r.dr.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    calc();
  })();
  </script>
</div>
<!-- 전세 vs 월세 비교 계산기 위젯 끝 -->
<h2>전세 vs 월세 비용 계산법</h2>
<p>전세 보증금과 월세 보증금은 계약이 끝나면 돌려받는 돈이라 "비용"이 아니에요. 대신 그 돈이 2년 동안 묶이면서 생기는 이자 부담과 놓친 이자가 비용이에요. 그래서 두 조건을 한 달 실부담으로 바꿔 비교해요.</p>
<ul>
  <li><strong>전세 월 실부담</strong> = 전세대출 × 대출 금리 ÷ 12 + (전세 보증금 − 대출) × 예금 금리 ÷ 12 + 전세 보증금 × 보증보험료율 ÷ 12</li>
  <li><strong>월세 월 실부담</strong> = 월세 + 월세 보증금 × 예금 금리 ÷ 12 − 월세 세액공제 ÷ 12</li>
  <li><strong>월세 세액공제(연)</strong> = min(1년 월세, 1,000만원) × 15% 또는 17%</li>
  <li><strong>2년 총비용</strong> = 월 실부담 × 24</li>
</ul>
<p>예를 들어 전세 3억원 중 2억원을 금리 4%로 대출받고 1억원은 내 돈으로 낸다고 해요. 예금 금리를 3%로 보면 대출이자 2억원 × 4% ÷ 12 = 66만 6,667원, 내 돈의 기회비용 1억원 × 3% ÷ 12 = 25만원이라서 <strong>전세는 월 91만 6,667원</strong>이 들어요. 같은 집을 보증금 5,000만원·월세 90만원에 구하면 90만원 + 5,000만원 × 3% ÷ 12(12만 5,000원) = <strong>월 102만 5,000원</strong>이라 전세가 월 10만 8,333원, 2년이면 260만원 싸요. 그런데 총급여 5,500만원 이하로 월세 세액공제 17%를 받는다면 1년 월세 1,080만원 중 한도 1,000만원 × 17% = 170만원(월 14만 1,667원)을 돌려받아 월세 실부담이 월 88만 3,333원으로 내려가고, 이번엔 <strong>월세가 월 3만 3,333원 유리</strong>해져요.</p>
<h2>항목별로 보면 무엇이 비용일까</h2>
<table>
  <thead><tr><th>항목</th><th>전세</th><th>월세</th></tr></thead>
  <tbody>
    <tr><td>매달 나가는 돈</td><td>전세대출 이자</td><td>월세</td></tr>
    <tr><td>보이지 않는 비용</td><td>내 돈(보증금 − 대출)의 기회비용</td><td>보증금의 기회비용(보통 전세보다 작음)</td></tr>
    <tr><td>선택 비용</td><td>전세보증보험료(연 약 0.097~0.211%, HUG 임차인 기준)</td><td>보증금이 크면 보증보험을 들기도 해요</td></tr>
    <tr><td>돌려받는 세금</td><td>전세대출 원리금 상환액 소득공제(요건 충족 시, 이 계산기엔 미반영)</td><td>월세 세액공제 15~17%, 연 1,000만원 한도</td></tr>
    <tr><td>계산 밖의 위험</td><td>보증금을 돌려받지 못할 위험이 커요</td><td>보증금이 작아 위험도 작아요. 대신 월세가 오를 수 있어요</td></tr>
  </tbody>
</table>
<h2>손익분기 전환율로 한 번에 판단하기</h2>
<p>보증금을 줄이는 대신 월세를 내는 조건은 "전환율"로 바꿔 볼 수 있어요. <strong>전환율 = 월세 × 12 ÷ (전세 보증금 − 월세 보증금)</strong>이에요. 위 예시라면 90만원 × 12 ÷ 2억 5,000만원 = 4.32%예요. 두 조건의 비용이 똑같아지는 전환율(손익분기 전환율)보다 실제 전환율이 낮으면 월세가, 높으면 전세가 유리해요. 계산기는 이 손익분기 전환율도 함께 보여 줘요.</p>
<p>아래 표는 전세 3억원과 보증금 5,000만원짜리 월세를 예금 금리 3%로 비교할 때, 대출 규모와 금리에 따라 손익분기 전환율과 그에 해당하는 월세가 어떻게 바뀌는지 정리한 거예요(세액공제·보증료 미반영). 월세가 이 금액보다 적으면 월세가 유리해요.</p>
<table>
  <thead><tr><th>전세대출</th><th>대출 금리</th><th>손익분기 전환율</th><th>같아지는 월세</th></tr></thead>
  <tbody>
    <tr><td>없음</td><td>-</td><td>3.00%</td><td>62만 5,000원</td></tr>
    <tr><td>1억원</td><td>3.5%</td><td>3.20%</td><td>66만 6,667원</td></tr>
    <tr><td>1억원</td><td>4.0%</td><td>3.40%</td><td>70만 8,333원</td></tr>
    <tr><td>1억원</td><td>4.5%</td><td>3.60%</td><td>75만원</td></tr>
    <tr><td>2억원</td><td>3.5%</td><td>3.40%</td><td>70만 8,333원</td></tr>
    <tr><td>2억원</td><td>4.0%</td><td>3.80%</td><td>79만 1,667원</td></tr>
    <tr><td>2억원</td><td>4.5%</td><td>4.20%</td><td>87만 5,000원</td></tr>
  </tbody>
</table>
<p>대출 비중이 크고 금리가 높을수록 전세 비용이 커져서 손익분기 전환율이 올라가요. 즉 대출을 많이 끼는 전세일수록 월세가 상대적으로 유리해져요.</p>
<p>주택임대차보호법은 계약 기간 중이나 갱신할 때 보증금을 월세로 바꾸면 전환율을 <strong>기준금리 + 2%</strong>(2026년 11월 26일 기준금리 3.25% → 5.25%)까지만 적용하게 해요. 손익분기 전환율이 5.25%보다 높으면 상한 안에서 바꾼 월세는 계산상 유리하고, 낮으면 상한까지 받는 조건은 전세보다 비싸요. 새로 맺는 계약에는 이 상한이 적용되지 않아서 시장 전환율이 더 높게 나오기도 해요.</p>
<h2>월세 세액공제 공제율과 한도</h2>
<table>
  <thead><tr><th>총급여(종합소득금액)</th><th>공제율</th><th>연간 한도</th><th>최대 공제액</th></tr></thead>
  <tbody>
    <tr><td>5,500만원 이하(4,500만원 이하)</td><td>17%</td><td>월세 1,000만원</td><td>170만원</td></tr>
    <tr><td>5,500만원 초과 8,000만원 이하(7,000만원 이하)</td><td>15%</td><td>월세 1,000만원</td><td>150만원</td></tr>
    <tr><td>8,000만원 초과</td><td>공제 대상 아님</td><td>-</td><td>-</td></tr>
  </tbody>
</table>
<p>무주택 세대의 세대주(세대주가 주택 관련 공제를 받지 않으면 세대원도 가능)가 전용 85㎡ 이하 또는 기준시가 4억원 이하 주택에 살면서 전입신고를 해야 받아요. 연말정산 때 임대차계약서 사본과 월세 이체 내역을 내요. 낼 세금(결정세액)이 공제액보다 적으면 그만큼만 줄어들어요. 2026년 8월 정부 세제개편안에는 2027년 지급분부터 한도를 1,200만원으로 올리고 15~34세 청년은 총급여 5,500만원을 넘어도 17%를 적용하는 내용이 담겼지만, 국회 의결 전이라 계산기는 현행 1,000만원 한도로 계산해요.</p>
<h2>계산에 들어가지 않는 것: 보증금 반환 위험</h2>
<p>계산상 전세가 싸더라도 보증금을 제때 돌려받지 못하면 그 손실은 이자 몇 년치를 훌쩍 넘어요. 전세를 고른다면 계약 전에 등기부등본으로 선순위 채권을 확인하고, 전세보증보험에 가입할 수 있는 집인지 먼저 따져 보세요. 집값 대비 보증금과 대출이 많아 보험 가입이 안 되는 집이라면, 월세로 보증금을 낮추는 쪽이 비용보다 위험 관리 면에서 나을 수 있어요.</p>
<h2>자주 묻는 질문</h2>
<h3>전세와 월세 중 어느 쪽이 더 유리한가요?</h3>
<p>정답은 금리에 따라 달라져요. 전세는 대출이자와 내 돈의 기회비용이, 월세는 월세와 보증금의 기회비용이 비용이에요. 대출 금리가 높고 대출 비중이 클수록 전세가 비싸지고, 예금 금리가 낮을수록 내 돈을 묶는 부담이 작아 전세가 유리해져요. 월세 세액공제를 받을 수 있다면 월세 쪽 실부담이 15~17%까지 줄어드니 함께 넣어 비교해 보세요.</p>
<h3>기회비용 금리는 몇 %로 넣어야 하나요?</h3>
<p>보증금으로 묶이는 내 돈을 대신 넣어 둘 수 있었던 곳의 연 금리를 넣으면 돼요. 보통은 지금 가입할 수 있는 정기예금 금리를 쓰고, 이자소득세 15.4%를 뺀 세후 금리를 넣으면 더 정확해요. 그 돈으로 대출을 갚을 계획이었다면 대출 금리를 넣는 것이 맞아요. 금리를 1%p씩 바꿔 넣어 보면 결과가 얼마나 민감한지 알 수 있어요.</p>
<h3>월세 세액공제는 누가 받을 수 있나요?</h3>
<p>총급여 8,000만원(종합소득금액 7,000만원) 이하인 무주택 세대의 세대주가 받을 수 있고, 세대주가 주택 관련 공제를 받지 않으면 세대원도 받을 수 있어요. 전용 85㎡ 이하이거나 기준시가 4억원 이하인 주택이어야 하고, 임대차계약서 주소로 전입신고가 되어 있어야 해요. 공제율은 총급여 5,500만원 이하 17%, 8,000만원 이하 15%이고, 연 월세 1,000만원까지 공제돼요.</p>
<h3>손익분기 전환율과 법정 전환율 5.25%는 어떻게 다른가요?</h3>
<p>손익분기 전환율은 내 대출 금리·예금 금리로 계산했을 때 전세와 월세 비용이 같아지는 비율이고, 법정 전환율 5.25%는 계약 중이나 갱신 때 집주인이 보증금을 월세로 바꾸며 받을 수 있는 상한(기준금리 3.25% + 2%)이에요. 실제 조건의 전환율이 손익분기보다 낮으면 월세가 유리하고, 갱신하면서 상한을 넘는 월세를 요구받았다면 상한까지만 내면 돼요.</p>
<h3>계산상 전세가 유리하면 전세를 고르면 되나요?</h3>
<p>비용만 보면 그렇지만, 보증금을 돌려받지 못할 위험은 이 계산에 들어가지 않아요. 전세는 보증금이 커서 집주인이 돌려주지 못하면 손실이 매우 커요. 등기부등본의 선순위 채권과 집값 대비 보증금 비율을 확인하고, 전세보증보험에 가입할 수 있는 집인지 먼저 확인한 뒤 결정하세요. 차이가 크지 않다면 보증금이 작은 쪽이 더 안전할 수 있어요.</p>
