        : '신문 구독료도 포함돼요. 총급여 7천만 원 이하일 때만 따로 30%를 받아요.';
      var k = high ? 'high' : 'low';
      $('[data-kids-hint]').textContent = '연말정산에서 기본공제를 받는 자녀 기준으로 1명당 기본 한도가 ' + comma(KID_LIMIT[k] / 1e4) + '만 원(최대 ' +
        comma(KID_LIMIT[k] * KID_MAX / 1e4) + '만 원) 늘어나요' + (sal ? (high ? '(총급여 7천만 원 초과).' : '(총급여 7천만 원 이하).') : '. 7천만 원 초과는 25만 원(최대 50만 원)이에요.') +
        ' 맞벌이면 자녀를 기본공제로 올린 사람만 받아요.';
      $('[data-rate-hint]').textContent = '과세표준 ' + RATES[st.rate][1] + ' 구간이에요. 작년 원천징수영수증의 과세표준으로 확인하고, 모르면 많은 직장인이 속하는 16.5%로 두세요.';
    }

    function hide(t) { result.classList.remove('kcd-show'); msg.textContent = t || ''; }

    function read() {
      return { sal: val(salI), c: val(useI.c), d: val(useI.d), m: val(useI.m), t: val(useI.t), b: val(useI.b), kids: st.kids };
    }

    function calc() {
      var o = read();
      salRead.textContent = salI.value ? '총급여 ' + korean(o.sal) : SAL_HINT;
      sync(o.sal);
      salI.classList.remove('kcd-bad');
      $$('[data-use]').forEach(function (i) { i.classList.remove('kcd-bad'); });
      if (!salI.value) return hide('');
      if (o.sal <= 0 || o.sal > MAX_SAL) { salI.classList.add('kcd-bad'); return hide(o.sal <= 0 ? '총급여를 1원 이상으로 넣어 주세요.' : '총급여는 10억 원 이하로 넣어 주세요.'); }
      var bad = $$('[data-use]').filter(function (i) { return val(i) > MAX_USE; });
      if (bad.length) { bad.forEach(function (i) { i.classList.add('kcd-bad'); }); return hide('사용액은 칸마다 10억 원 이하로 넣어 주세요.'); }
      var r = compute(o);
      if (r.total <= 0) return hide('사용액을 한 칸 이상 넣어 주세요.');
      msg.textContent = '';
      render(o, r);
      result.classList.add('kcd-show');
    }

    function render(o, r) {
      var rate = RATES[st.rate][0], save = Math.floor(r.final * rate);
      $('[data-big]').innerHTML = comma(r.final) + '<small>원</small>';
      $('[data-sub]').innerHTML = r.final > 0
        ? '세금 약 <b>' + won(save) + '</b> 감소 (한계세율 ' + pct(rate) + ')'
        : '총급여의 25%까지 <b>' + won(r.short) + '</b> 더 써야 공제가 시작돼요';
      // 사용액 vs 25% 문턱 막대
      var cap = Math.max(r.total, r.min) || 1;
      $('[data-bar]').style.width = Math.min(r.total / cap * 100, 100) + '%';
      $('[data-bar-l]').textContent = '사용액 ' + korean(r.total);
      $('[data-bar-r]').textContent = '25% 문턱 ' + korean(r.min);

      // 다음 1만 원: 수단마다 1만 원을 더했을 때 공제액이 얼마나 늘어나는지 직접 다시 계산
      var keys = r.low ? ['c', 'd', 'm', 't', 'b'] : ['c', 'd', 'm', 't'];
      var inc = {}, best = 0;
      keys.forEach(function (key) {
        var p = {}; for (var x in o) p[x] = o[x];
        p[key] += 1e4;
        inc[key] = compute(p).final - r.final;
        if (inc[key] > best) best = inc[key];
      });
      $('[data-next]').innerHTML = keys.map(function (key) {
        var cls = inc[key] <= 0 ? ' class="kcd-zero"' : (inc[key] === best ? ' class="kcd-best"' : '');
        return '<tr' + cls + '><th>' + NAME[key] + '</th><td>+' + won(inc[key]) + '</td><td>−' + won(Math.floor(inc[key] * rate)) + '</td></tr>';
      }).join('');

      // 안내 문구
      var adv, room = r.limit - r.base;
      if (r.short > 0) {
        adv = '총급여의 25%인 <b>' + won(r.min) + '</b>까지 <b>' + won(r.short) + '</b> 남았어요. 이 문턱까지는 어떤 수단으로 써도 공제가 똑같이 0원이라, 할인·포인트 혜택이 큰 카드를 쓰는 편이 나아요. 문턱을 넘은 뒤부터 체크카드·현금영수증(30%)이 신용카드(15%)의 두 배예요.';
      } else if (r.ded < r.limit) {
        adv = (inc.d > inc.c
          ? '25% 문턱을 넘었어요. 지금부터는 <b>체크카드·현금영수증</b>이 1만 원당 ' + won(inc.d) + ' 공제로 신용카드(' + won(inc.c) + ')보다 유리하고, 전통시장·대중교통은 ' + won(inc.m) + '이에요. '
          : '25% 문턱을 넘었지만 문턱의 일부를 공제율이 높은 사용분으로 채운 상태라, 지금은 어떤 수단으로 1만 원을 더 써도 공제가 ' + won(inc.c) + '씩 늘어요. ') +
          '기본 한도 ' + won(r.limit) + '까지 공제 대상이 ' + won(room) + ' 남았어요.';
      } else if (r.add < r.addLimit) {
        adv = '기본 한도 <b>' + won(r.limit) + '</b>를 다 채웠어요. 이제 일반 신용카드·체크카드 사용분은 공제가 늘지 않고, <b>' + (r.low ? '전통시장·대중교통·문화' : '전통시장·대중교통') + '</b> 사용분만 추가 한도 ' + won(r.addLimit) + ' 안에서 더 공제돼요(남은 추가 한도 ' + won(r.addLimit - r.add) + ').';
      } else {
        adv = '<b>공제 한도를 모두 채웠어요.</b> 기본 한도 ' + won(r.limit) + (r.add > 0 ? ' + 추가 공제 ' + won(r.add) : '') + '까지 받았고, ' + (r.add >= r.addLimit ? '추가 한도도 찼어요. ' : '') + '이제는 어떤 수단으로 써도 공제가 늘지 않으니 혜택이 큰 카드를 쓰세요.';
      }
      $('[data-advice]').innerHTML = adv;

      function set(k, v) { $('[data-r="' + k + '"]').textContent = v; }
      set('total', won(r.total));
      set('min', won(r.min));
      var gl = [];
      keys.forEach(function (key) { if (r.g[key]) gl.push(NAME[key].split('·')[0] + ' ' + pct(RATE[key])); });
      set('grosslab', gl.join(' · ') || '사용액 × 수단별 공제율');
      set('gross', won(r.gross));
      set('excllab', ['사용액이 25%에 못 미쳐 전액 제외', '최저사용금액 × 15% (신용카드로 채움)', '신용카드 15% + 나머지 30%로 채움', '신용·체크 등 + 나머지 40%로 채움'][r.tier]);
      set('excl', '−' + won(r.excl));
      set('ded', won(r.ded));
      set('baselab', '한도 ' + won(r.limit) + (r.kidAdd ? ' (자녀 ' + r.kids + '명 +' + comma(r.kidAdd / 1e4) + '만 원 포함)' : ''));
      set('base', won(r.base));
      set('addlab', r.over > 0 ? '한도 ' + won(r.addLimit) + ', 대상 ' + won(r.special) : '기본 한도 안이라 없음');
      set('add', won(r.add));
      set('final', won(r.final));
      set('savelab', '공제액 × ' + pct(rate) + ' (추정)');
      set('save', won(save));

      var f = [];
      f.push('최저사용금액 = ' + comma(o.sal) + ' × 25% = ' + comma(r.min) + '원');
      if (r.tier === 0) f.push('사용액 ' + comma(r.total) + '원이 최저사용금액보다 적어 <b>공제 0원</b>');
      else {
        f.push('공제 대상 = ' + comma(r.gross) + ' − ' + comma(r.excl) + ' = ' + comma(r.ded) + '원');
        f.push('기본 공제 = min(' + comma(r.ded) + ', ' + comma(r.limit) + ') = ' + comma(r.base) + '원');
        if (r.over > 0) f.push('추가 공제 = min(' + comma(r.over) + ', ' + comma(r.addLimit) + ', ' + comma(r.special) + ') = ' + comma(r.add) + '원');
        f.push('소득공제액 = <b>' + comma(r.final) + '원</b>, 절세액 ≈ ' + comma(r.final) + ' × ' + pct(rate) + ' = ' + comma(save) + '원');
      }
      $('[data-formula]').innerHTML = f.map(function (s) { return '<p>' + s + '</p>'; }).join('');

      var lines = ['[신용카드 소득공제 계산 결과 (2026년 사용분)]', '총급여: ' + won(o.sal)];
      keys.forEach(function (key) { if (o[key]) lines.push(NAME[key] + ': ' + won(o[key])); });
      lines.push('자녀: ' + (st.kids ? (st.kids >= 2 ? '2명 이상' : '1명') : '없음'));
      lines.push('사용액 합계: ' + won(r.total) + ' / 최저사용금액(25%): ' + won(r.min));
      lines.push('공제 대상 금액: ' + won(r.ded));
      lines.push('기본 공제: ' + won(r.base) + ' (한도 ' + won(r.limit) + ')');
      lines.push('추가 공제: ' + won(r.add));
      lines.push('소득공제액: ' + won(r.final));
      lines.push('예상 절세액: 약 ' + won(save) + ' (한계세율 ' + pct(rate) + ')');
      lines.push('※ 참고용 계산이며 세무 자문이 아니에요.');
      lastText = lines.join('\n');
    }

    function money(i) {
      i.addEventListener('input', function () {
        var v = digits(i.value).slice(0, 12);
        i.value = v ? comma(+v) : '';
        calc();
      });
    }
    money(salI);
    Object.keys(useI).forEach(function (k) { money(useI[k]); });
    $$('[data-kids]').forEach(function (b) { b.addEventListener('click', function () { st.kids = +b.dataset.kids; calc(); }); });

    $('[data-reset]').addEventListener('click', function () {
      salI.value = ''; Object.keys(useI).forEach(function (k) { useI[k].value = ''; });
      st = { kids: 0, rate: 1 };
      hide(''); calc(); salI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    calc();
  })();
  </script>
</div>
<!-- 신용카드 소득공제 계산기 위젯 끝 -->
<h2>신용카드 소득공제 계산법</h2>
<p>신용카드 등 사용금액 소득공제는 조세특례제한법 제126조의2에 따라 아래 순서로 계산해요. 근로소득이 있는 직장인만 받을 수 있어요.</p>
<ol>
  <li><strong>최저사용금액 구하기:</strong> 총급여 × 25%. 이 금액까지는 공제가 없어요.</li>
  <li><strong>수단별 공제율 곱하기:</strong> 신용카드 15%, 체크카드·직불카드·선불카드·현금영수증 30%, 도서·신문·공연·박물관·미술관·영화·수영장·체력단련장 30%(총급여 7천만 원 이하만), 전통시장 40%, 대중교통 40%.</li>
  <li><strong>공제 제외 금액 빼기:</strong> 최저사용금액은 공제율이 낮은 신용카드 사용분부터 채운 것으로 봐요. 신용카드로 25%를 다 채웠다면 최저사용금액 × 15%만 빼고, 모자라면 체크카드 등(30%), 그다음 전통시장·대중교통(40%) 순서로 채워요.</li>
  <li><strong>기본 한도 적용:</strong> 총급여 7천만 원 이하 300만 원, 초과 250만 원. 2026년 사용분부터 기본공제 받는 자녀 1명당 50만 원(최대 100만 원), 7천만 원 초과는 1명당 25만 원(최대 50만 원)이 더해져요.</li>
  <li><strong>추가 공제:</strong> 기본 한도를 넘은 금액은 전통시장·대중교통·문화 사용분 공제액 범위에서 7천만 원 이하 300만 원, 초과 200만 원(전통시장·대중교통만)까지 더 공제해요.</li>
</ol>
<p>예를 들어 총급여 5천만 원인 직장인이 2026년에 신용카드 1,500만 원, 체크카드 500만 원, 전통시장 100만 원, 대중교통 100만 원을 썼다면 이렇게 계산해요.</p>
<ul>
  <li>최저사용금액: 5천만 원 × 25% = <strong>1,250만 원</strong> (사용액 합계 2,200만 원이라 문턱을 넘었어요)</li>
  <li>공제율 적용 합계: 1,500만 × 15% + 500만 × 30% + 100만 × 40% + 100만 × 40% = <strong>455만 원</strong></li>
  <li>공제 제외 금액: 신용카드로 1,250만 원을 다 채웠으니 1,250만 × 15% = <strong>187만 5천 원</strong></li>
  <li>공제 대상 금액: 455만 − 187만 5천 = 267만 5천 원 → 기본 한도 300만 원 안이라 <strong>소득공제 2,675,000원</strong></li>
  <li>한계세율 16.5%(지방소득세 포함)라면 세금이 약 <strong>441,375원</strong> 줄어요.</li>
</ul>
<p>이 사람이 남은 기간에 1만 원을 더 쓴다면 신용카드는 공제가 1,500원, 체크카드는 3,000원, 전통시장·대중교통은 4,000원 늘어요. 25%를 넘긴 뒤에는 체크카드가 신용카드의 두 배라는 말이 여기서 나와요.</p>

