    @media (prefers-reduced-motion:reduce){.kcb .kcb-result,.kcb .kcb-in,.kcb .kcb-btn,.kcb .kcb-chip,.kcb .kcb-seg button,.kcb .kcb-year summary::after{transition:none}}
  </style>

  <p class="kcb-title">육아 지원금 총액 계산기</p>
  <p class="kcb-desc">출생일만 넣으면 첫만남이용권·부모급여·아동수당·양육수당을 아동수당이 끝날 때까지 월별로 더해 드려요.</p>

  <label class="kcb-label" for="kcb-y"><span>출생일 <small class="kcb-small">(예정일도 돼요)</small></span><button type="button" class="kcb-link" data-today>오늘로</button></label>
  <div class="kcb-row">
    <div class="kcb-field kcb-y"><input class="kcb-in" id="kcb-y" data-y inputmode="numeric" maxlength="4" placeholder="2026" aria-label="출생 연도"><span class="kcb-unit">년</span></div>
    <div class="kcb-field"><input class="kcb-in" data-m inputmode="numeric" maxlength="2" placeholder="3" aria-label="출생 월"><span class="kcb-unit">월</span></div>
    <div class="kcb-field"><input class="kcb-in" data-d inputmode="numeric" maxlength="2" placeholder="15" aria-label="출생 일"><span class="kcb-unit">일</span></div>
  </div>

  <p class="kcb-label">몇째 아이인가요?</p>
  <div class="kcb-seg" data-order role="group" aria-label="출생 순위">
    <button type="button" data-v="1" class="kcb-on" aria-pressed="true">첫째</button>
    <button type="button" data-v="2" aria-pressed="false">둘째 이상</button>
  </div>

  <p class="kcb-label">어린이집·유치원은 언제부터 다니나요?</p>
  <div class="kcb-chips" data-care role="group" aria-label="어린이집 이용 시작">
    <button type="button" class="kcb-chip kcb-on" data-v="-1" aria-pressed="true">안 다님 (집에서)</button>
    <button type="button" class="kcb-chip" data-v="6" aria-pressed="false">생후 6개월부터</button>
    <button type="button" class="kcb-chip" data-v="12" aria-pressed="false">만 1세부터</button>
    <button type="button" class="kcb-chip" data-v="24" aria-pressed="false">만 2세부터</button>
    <button type="button" class="kcb-chip" data-v="36" aria-pressed="false">만 3세부터</button>
  </div>

  <p class="kcb-msg" data-msg role="status" aria-live="polite"></p>

  <div class="kcb-result" data-result aria-live="polite">
    <div class="kcb-result-inner">
      <div data-infos></div>
      <div class="kcb-main">
        <p class="kcb-main-label" data-main-label>아동수당이 끝날 때까지 받는 돈</p>
        <p class="kcb-big" data-big></p>
        <p class="kcb-sum" data-sum></p>
      </div>
      <div class="kcb-grid">
        <div class="kcb-card"><p class="kcb-card-k">오늘까지 받은 금액</p><p class="kcb-card-v" data-got></p></div>
        <div class="kcb-card"><p class="kcb-card-k">앞으로 받을 금액</p><p class="kcb-card-v" data-left></p></div>
      </div>

      <p class="kcb-h">제도별 합계</p>
      <table class="kcb-tbl">
        <thead><tr><th scope="col">제도</th><th scope="col" style="text-align:right">금액</th></tr></thead>
        <tbody data-by></tbody>
      </table>

      <p class="kcb-h">연도별 월 수령액 <small class="kcb-small">(눌러서 펼치기)</small></p>
      <div class="kcb-years" data-years></div>

      <div class="kcb-note">
        <p>2026년 11월 기준 보건복지부 안내로 계산했어요. 2027년 이후 금액은 지금 금액이 그대로라고 보고 더했고, 아동수당 나이는 아동수당법에 정해진 대로 2027년 만 10세 미만, 2030년부터 만 13세 미만으로 넓혔어요.</p>
        <p><b>지자체 출산·양육 지원금은 별도예요.</b> 비수도권·인구감소지역 아동수당 추가분, 농어촌·장애아동 양육수당, 어린이집 보육료(만 2세부터)와 유치원 누리과정 지원도 합계에 넣지 않았어요. 정확한 금액은 복지로(129)나 주민센터에서 확인해 주세요.</p>
      </div>
      <div class="kcb-actions">
        <button type="button" class="kcb-btn" data-reset>다시 입력</button>
        <button type="button" class="kcb-btn kcb-primary" data-copy>결과 복사</button>
      </div>
    </div>
  </div>

  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-kcb]');
    if (!root || root.__kcb) return;
    root.__kcb = true;

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var yI = $('[data-y]'), mI = $('[data-m]'), dI = $('[data-d]');
    var msg = $('[data-msg]'), result = $('[data-result]');
    var lastText = '';

    // ===== 기준 금액 (2026년 11월 기준, 2027년 이후는 같은 값으로 가정) =====
    var R = {
      voucher: { 1: 2000000, 2: 3000000 },      // 첫만남이용권 (2024. 1. 1. 이후 출생, 첫째 200만·둘째 이상 300만)
      pg0: 1000000, pg1: 500000,                 // 부모급여 0세(0~11개월)·1세(12~23개월)
      allowance: 100000,                         // 아동수당 월 기본액
      home: 100000,                              // 가정양육수당 24~85개월(86개월 미만)
      fullFrom: 20240101,                        // 이 날 이후 출생아만 전체 계산(지금 제도가 처음부터 적용)
      partialFrom: 20170101,                     // 2017~2023년생은 앞으로 받을 금액만
      newSystem: 20270701                        // 아이맞이지원금 개편안 적용 예정 출생일(국회 심의 중)
    };
    // 0세반 보육료(부모보육료) 지원단가: 어린이집 이용 시 부모급여에서 이 금액을 뺀 차액만 현금
    function fee0(y, m) {
      var k = y * 100 + m;
      if (k < 202507) return 540000;
      if (k < 202601) return 567000;
      return 584000;
    }
    // 아동수당 대상 나이(개월 미만). 생일이 속한 달의 전달까지 받음
    function capMonths(y, m, birthY) {
      if (y < 2026) return 96;                   // ~2025: 만 8세 미만
      if (birthY === 2017) return 156;            // 2017년생 특례: 만 13세 전까지 끊김 없이
      if (y === 2026) return 108;                // 2026: 만 9세 미만 (1월분부터 소급)
      if (y === 2027) return 120;                // 2027: 만 10세 미만
      if (y === 2028) return 132;
      if (y === 2029) return 144;
      return 156;                                // 2030~: 만 13세 미만
    }

    function today() { var n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); }
    function fmt(d) { return d.getFullYear() + '. ' + (d.getMonth() + 1) + '. ' + d.getDate() + '.'; }
    function ym(y, m) { return y + '. ' + m + '.'; }
    function comma(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function won(n) {
      if (n === 0) return '0원';
      var man = Math.floor(n / 10000), rest = n % 10000;
      if (!man) return comma(rest) + '원';
      return comma(man) + '만' + (rest ? ' ' + comma(rest) + '원' : '원');
    }
    function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
    function ageText(i) {
      if (i < 24) return i + '개월';
      return '만 ' + Math.floor(i / 12) + '세';
    }

    var opt = { order: 1, care: -1 };

    function simulate(birth, order, care, now) {
      var by = birth.getFullYear(), bm = birth.getMonth() + 1;
      var key = by * 10000 + bm * 100 + birth.getDate();
      var full = key >= R.fullFrom;
      var months = [], by_ = { voucher: 0, pgCash: 0, pgCare: 0, allowance: 0, home: 0 };
      var got = 0, left = 0, cash = 0, card = 0;
      var nowKey = now.getFullYear() * 10000 + (now.getMonth() + 1) * 100 + now.getDate();
      for (var i = 0; i < 160; i++) {
        var y = by + Math.floor((bm - 1 + i) / 12), m = (bm - 1 + i) % 12 + 1;
        var pay = y * 10000 + m * 100 + 25;                  // 매월 25일 지급 기준
        if (i === 0 && key > pay) pay = (m === 12 ? (y + 1) * 10000 + 125 : pay + 100); // 25일 뒤 출생은 다음 달 25일에 소급
        var paid = key <= nowKey && pay <= nowKey;
        if (!full && paid) continue;                         // 2023년 이전 출생: 앞으로 받을 달만
        var items = [], sum = 0;
        var inCare = care >= 0 && i >= care;
        if (full && i === 0) {
          var v = R.voucher[order];
          items.push({ k: 'voucher', t: '첫만남이용권', a: v }); by_.voucher += v; card += v; sum += v;
        }
        if (full && i < 24) {
          var pg = i < 12 ? R.pg0 : R.pg1, c = pg, b = 0;
          if (inCare) { b = i < 12 ? Math.min(pg, fee0(y, m)) : pg; c = pg - b; }
          if (c) { items.push({ k: 'pgCash', t: '부모급여' + (b ? '(차액)' : ''), a: c }); by_.pgCash += c; cash += c; }
          if (b) { items.push({ k: 'pgCare', t: '부모급여→보육료', a: b }); by_.pgCare += b; card += b; }
          sum += pg;
        }
        if (i < capMonths(y, m, by)) {
          items.push({ k: 'allowance', t: '아동수당', a: R.allowance }); by_.allowance += R.allowance; cash += R.allowance; sum += R.allowance;
        }
        if (!inCare && i >= 24 && i < 86) {
          items.push({ k: 'home', t: '양육수당', a: R.home }); by_.home += R.home; cash += R.home; sum += R.home;
        }
        if (!sum) continue;
        // 첫만남이용권은 출생일에 받는다고 보고, 나머지는 그달 25일
        if (paid) got += sum;
        else if (full && i === 0 && key <= nowKey) { got += R.voucher[order]; left += sum - R.voucher[order]; }
        else left += sum;
        months.push({ i: i, y: y, m: m, items: items, sum: sum, paid: paid });
      }
      return { full: full, key: key, months: months, by: by_, got: got, left: left, total: got + left, cash: cash, card: card };
    }

    function hide(text) {
      result.classList.remove('kcb-show');
      msg.textContent = text || '';
    }

    function calc() {
      var y = +yI.value, m = +mI.value, d = +dI.value;
      if (yI.value.length < 4 || !mI.value || !dI.value) return hide('');
      var birth = new Date(y, m - 1, d);
      if (m < 1 || m > 12 || birth.getMonth() !== m - 1 || birth.getDate() !== d || y < 1900) return hide('날짜를 다시 확인해 주세요.');
      var now = today();
      if ((birth - now) / 864e5 > 300) return hide('출산 예정일은 오늘부터 300일 안의 날짜로 넣어 주세요.');
      var key = y * 10000 + m * 100 + d;
      if (key < R.partialFrom) return hide('2016년 이전에 태어난 아이는 아동수당 대상 나이(2026년 만 9세 미만)를 지나 남은 지원금이 없어요.');

      var r = simulate(birth, opt.order, opt.care, now);
      if (!r.months.length) return hide('앞으로 받을 아동수당·양육수당이 없어요. 아동수당 대상 나이를 지났어요.');
      msg.textContent = '';

      var infos = [];
      if (!r.full) infos.push('2023년 이전에 태어난 아이는 그때 제도(부모급여 금액 등)가 지금과 달라, <b>이번 달부터 앞으로 받을 아동수당·양육수당만</b> 계산했어요.' + (y === 2017 ? ' 2017년생은 특례로 만 13세 전까지 끊김 없이 받아요.' : ''));
      if (key >= R.newSystem) infos.push('2027. 7. 1. 이후 태어나는 아이는 정부가 추진 중인 <b>아이맞이지원금·아동기본수당</b>(2027년 예산안, 국회 심의 중)으로 바뀔 수 있어요. 아래는 지금 제도로 계산한 금액이에요.');
      $('[data-infos]').innerHTML = infos.map(function (t) { return '<p class="kcb-info">' + t + '</p>'; }).join('');

      var first = r.months[0], last = r.months[r.months.length - 1];
      $('[data-main-label]').textContent = r.full ? '아동수당이 끝날 때까지 받는 돈' : '이번 달부터 앞으로 받을 돈';
      $('[data-big]').textContent = won(r.total);
      $('[data-sum]').innerHTML = '<span class="kcb-nb">' + ym(first.y, first.m) + '</span> ~ <span class="kcb-nb">' + ym(last.y, last.m) + '</span> · 현금 ' +
        '<span class="kcb-nb">' + won(r.cash) + '</span>' + (r.card ? ' + 이용권·보육료 <span class="kcb-nb">' + won(r.card) + '</span>' : '');
      $('[data-got]').textContent = r.full ? won(r.got) : '계산 안 함';
      $('[data-left]').textContent = won(r.left);

      // 제도별 합계
      function span(k) {
        var a = null, b = null;
        r.months.forEach(function (mo) { mo.items.forEach(function (it) { if (it.k === k) { if (!a) a = mo; b = mo; } }); });
        if (!a) return '';
        return a === b ? ym(a.y, a.m) : ym(a.y, a.m) + ' ~ ' + ym(b.y, b.m) + ' (' + r.months.filter(function (mo) { return mo.items.some(function (it) { return it.k === k; }); }).length + '개월)';
      }
      var rows = [
        ['voucher', '첫만남이용권', (opt.order === 1 ? '첫째' : '둘째 이상') + ', 국민행복카드 이용권'],
        ['pgCash', '부모급여 (현금)', '0세 월 100만원, 1세 월 50만원' + (opt.care >= 0 && opt.care < 24 ? ', 어린이집 다니는 달은 차액만' : '')],
        ['pgCare', '부모급여 → 보육료', '어린이집 다니는 달은 보육료 바우처로 대신 받아요'],
        ['allowance', '아동수당', '월 10만원, 생일 달의 전달까지'],
        ['home', '가정양육수당', '24~85개월, 어린이집·유치원 안 다닐 때 월 10만원']
      ];
      var copyRows = [];
      $('[data-by]').innerHTML = rows.filter(function (x) { return r.by[x[0]] > 0; }).map(function (x) {
        copyRows.push('- ' + x[1] + ': ' + won(r.by[x[0]]) + ' (' + span(x[0]) + ')');
        return '<tr><td>' + x[1] + '<span class="kcb-sub2">' + esc(span(x[0])) + '</span><span class="kcb-sub2">' + x[2] + '</span></td><td class="kcb-r">' + won(r.by[x[0]]) + '</td></tr>';
      }).join('') + '<tr class="kcb-tot"><td>합계</td><td class="kcb-r">' + won(r.total) + '</td></tr>';

      // 연도별 접기
      var years = {}, order = [];
      r.months.forEach(function (mo) { if (!years[mo.y]) { years[mo.y] = []; order.push(mo.y); } years[mo.y].push(mo); });
      var nowY = now.getFullYear(), copyYears = [];
      $('[data-years]').innerHTML = order.map(function (yy) {
        var list = years[yy], tot = 0, allPaid = true;
        list.forEach(function (mo) { tot += mo.sum; if (!mo.paid) allPaid = false; });
        copyYears.push('- ' + yy + '년: ' + won(tot));
        var open = yy === Math.max(nowY, order[0]) ? ' open' : '';
        var a0 = list[0].i, a1 = list[list.length - 1].i;
        var ageRange = ageText(a0) === ageText(a1) ? ageText(a0) : ageText(a0) + '~' + ageText(a1).replace('만 ', '');
        return '<details class="kcb-year' + (allPaid ? ' kcb-past' : '') + '"' + open + '><summary><span>' + yy + '년 <small>' + ageRange + '</small></span><span class="kcb-ys">' + won(tot) + '</span></summary><ul class="kcb-months">' +
          list.map(function (mo) {
            return '<li' + (mo.paid ? ' class="kcb-done"' : '') + '><span class="kcb-mm">' + mo.m + '월<small>' + ageText(mo.i) + '</small></span><span class="kcb-what">' +
              mo.items.map(function (it) { return it.t + ' ' + won(it.a); }).join(' · ') + (mo.paid ? '<span class="kcb-tag">받음</span>' : '') +
              '</span><span class="kcb-amt">' + won(mo.sum) + '</span></li>';
          }).join('') + '</ul></details>';
      }).join('');

      result.classList.add('kcb-show');
      var careTxt = { '-1': '안 다님', '6': '생후 6개월부터', '12': '만 1세부터', '24': '만 2세부터', '36': '만 3세부터' }[String(opt.care)];
      lastText = '[육아 지원금 총액 계산 결과]\n출생일: ' + fmt(birth) + ' · ' + (opt.order === 1 ? '첫째' : '둘째 이상') + ' · 어린이집 ' + careTxt +
        '\n' + (r.full ? '총액(아동수당 끝날 때까지): ' : '이번 달부터 앞으로 받을 금액: ') + won(r.total) + ' (' + ym(first.y, first.m) + ' ~ ' + ym(last.y, last.m) + ')' +
        (r.full ? '\n오늘까지 받은 금액: ' + won(r.got) + '\n앞으로 받을 금액: ' + won(r.left) : '') +
        '\n\n[제도별]\n' + copyRows.join('\n') + '\n\n[연도별]\n' + copyYears.join('\n') +
        '\n\n※ ' + fmt(now) + ' 기준, 2027년 이후는 현재 금액 유지 가정. 지자체 지원금·지역 추가분 별도.';
    }

    function bind(input, next, len) {
      input.addEventListener('input', function () {
        var v = input.value.replace(/\D/g, '').slice(0, len);
        if (v !== input.value) input.value = v;
        if (next && v.length === len) next.focus();
        if (next === dI && len === 2 && v.length === 1 && +v > 1) dI.focus();
        if (input === dI && v.length === 1 && +v > 3) dI.blur();
        calc();
      });
    }
    bind(yI, mI, 4); bind(mI, dI, 2); bind(dI, null, 2);
    [mI, dI].forEach(function (inp, i) {
      inp.addEventListener('keydown', function (e) {
        if (e.key === 'Backspace' && !inp.value) { e.preventDefault(); (i === 0 ? yI : mI).focus(); }
      });
    });
    yI.addEventListener('paste', function (e) {
      var t = (e.clipboardData || window.clipboardData).getData('text').replace(/\D/g, '');
      if (t.length === 8) { e.preventDefault(); yI.value = t.slice(0, 4); mI.value = String(+t.slice(4, 6)); dI.value = String(+t.slice(6, 8)); calc(); }
    });

    $('[data-today]').addEventListener('click', function () {
      var t = today();
      yI.value = t.getFullYear(); mI.value = t.getMonth() + 1; dI.value = t.getDate();
      calc();
    });

    function group(sel, key, cls) {
      $$(sel + ' button').forEach(function (b) {
        b.addEventListener('click', function () {
          $$(sel + ' button').forEach(function (x) { x.classList.remove(cls); x.setAttribute('aria-pressed', 'false'); });
          b.classList.add(cls); b.setAttribute('aria-pressed', 'true');
          opt[key] = +b.getAttribute('data-v');
          calc();
        });
      });
    }
    group('[data-order]', 'order', 'kcb-on');
    group('[data-care]', 'care', 'kcb-on');

    $('[data-reset]').addEventListener('click', function () {
      yI.value = mI.value = dI.value = '';
      hide(''); yI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (!result.classList.contains('kcb-show')) { msg.textContent = '먼저 출생일을 입력해 주세요.'; return; }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });
