  <script>
  (function () {
    var me = document.currentScript || (function (s) { return s[s.length - 1]; })(document.getElementsByTagName('script'));
    var root = me.closest('[data-kst]');
    if (!root || root.__kst) return;
    root.__kst = true;

    // ===== 바뀔 수 있는 값: 매년 교육부 고시가 나오면 여기만 고치면 돼요 (README.md "매년 할 일" 참고) =====
    // 상환기준소득(연간 소득금액). 괄호는 총급여 환산액. 2026.11.26 현재 2027년 소득분 고시는 발표 전.
    var R = {
      '2025': { base: 18980000, gross: 28510000, hint: '2025년 소득분 상환기준소득: 소득금액 1,898만원 (총급여 약 2,851만원). 2026년 4월 통지, 2026년 7월~2027년 6월 원천공제.' },
      '2026': { base: 20560000, gross: 30370000, hint: '2026년 소득분 상환기준소득: 소득금액 2,056만원 (총급여 약 3,037만원). 2027년 4월쯤 통지, 2027년 7월부터 원천공제.' }
    };
    var MIN_WITHHOLD = 360000; // 의무상환액이 36만원 미만이면 원천공제 없이 통지서로 직접 납부
    // ===== 바뀔 수 있는 값 끝 =====

    var $ = function (s) { return root.querySelector(s); };
    var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
    var incI = $('[data-inc]'), balI = $('[data-bal]'), rateI = $('[data-rate]');
    var msg = $('[data-msg]'), result = $('[data-result]');
    var year = '2026', type = 'w', pct = 20, lastText = '';

    function comma(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
    function won(n) { return comma(Math.floor(n)) + '원'; }
    function man(n) { return n % 10000 ? comma(n) + '원' : comma(n / 10000) + '만원'; }
    function num(inp) { return +String(inp.value).replace(/\D/g, '') || 0; }
    function hide(text) { result.classList.remove('kst-show'); msg.textContent = text || ''; }

    // 근로소득공제 (소득세법 제47조, 한도 2,000만원)
    function earnedDeduction(g) {
      var d;
      if (g <= 5e6) d = g * 0.7;
      else if (g <= 15e6) d = 3.5e6 + (g - 5e6) * 0.4;
      else if (g <= 45e6) d = 7.5e6 + (g - 15e6) * 0.15;
      else if (g <= 1e8) d = 12e6 + (g - 45e6) * 0.05;
      else d = Math.min(14.75e6 + (g - 1e8) * 0.02, 2e7);
      return Math.floor(d + 1e-6);
    }

    // 해마다: 잔액에 1년 이자를 더한 뒤 의무상환액만큼 갚는다 (소득·금리 고정 가정)
    function payoff(bal, pay, rate) {
      if (pay <= 0) return null;
      if (pay >= bal) return { years: 1, paid: bal };
      if (rate > 0 && pay <= Math.floor(bal * rate + 1e-6)) return { never: true };
      var b = bal, years = 0, paid = 0;
      while (b > 0 && years < 60) {
        b = Math.floor(b * (1 + rate) + 1e-6);
        var p = Math.min(pay, b);
        b -= p; paid += p; years++;
      }
      if (b > 0) return { never: true };
      return { years: years, paid: paid };
    }

    function calc() {
      var c = R[year];
      var incRaw = incI.value, balRaw = balI.value, rRaw = String(rateI.value).trim();
      if (!incRaw) return hide('');
      var inc = num(incI), bal = num(balI);
      if (!inc) return hide(type === 'w' ? '연 총급여를 입력해 주세요.' : '연간 소득금액을 입력해 주세요.');
      if (inc > 10000000000) return hide('금액을 다시 확인해 주세요.');
      if (balRaw && !bal) return hide('대출 잔액을 다시 확인해 주세요. 다 갚았다면 칸을 비워 두세요.');
      if (bal > 1000000000) return hide('대출 잔액을 다시 확인해 주세요.');
      if (rRaw === '' || !/^\d{1,2}(\.\d{1,2})?$/.test(rRaw) || +rRaw > 20) return hide('금리는 0~20 사이 숫자로 넣어 주세요 (예: 1.7).');
      var rate = +rRaw / 100;
      msg.textContent = '';

      var ded = type === 'w' ? earnedDeduction(inc) : 0;
      var income = inc - ded;
      var over = Math.max(income - c.base, 0);
      var raw = Math.floor(over * pct / 100 + 1e-6);
      var capped = bal > 0 && raw > bal;
      var annual = capped ? bal : raw;
      var monthly = Math.floor(annual / 12);

      var tb = $('[data-rows]');
      tb.innerHTML = '';
      function row(label, sub, amt, note, cls) {
        var tr = document.createElement('tr'); if (cls) tr.className = cls;
        var th = document.createElement('th'); th.textContent = label;
        if (sub) { var s = document.createElement('small'); s.textContent = sub; th.appendChild(s); }
        var td = document.createElement('td'); td.textContent = amt;
        if (note) { var s2 = document.createElement('small'); s2.textContent = note; td.appendChild(s2); }
        tr.appendChild(th); tr.appendChild(td); tb.appendChild(tr);
      }
      if (type === 'w') {
        row('연 총급여', '비과세 수당 제외', won(inc), '');
        row('근로소득공제', '소득세법 제47조', '− ' + won(ded), '');
      }
      row('연간 소득금액', type === 'w' ? '총급여 − 근로소득공제' : '직접 입력', won(income), '');
      row('상환기준소득', year + '년 소득분', '− ' + man(c.base), '');
      row('기준 초과 소득', '', won(over), '');
      row('연 의무상환액', '초과 소득 × ' + pct + '%', won(annual), capped ? '잔액까지만 (원래 ' + won(raw) + ')' : '', 'kst-total');
      if (type === 'w' && annual > 0) row('월 원천공제액', annual < MIN_WITHHOLD ? '36만원 미만이라 원천공제 없음' : '의무상환액 ÷ 12', annual < MIN_WITHHOLD ? '직접 납부' : '약 ' + won(monthly), '');

      var po = null;
      if (bal > 0 && annual > 0) {
        po = payoff(bal, annual, rate);
        if (po && po.never) row('다 갚기까지', '소득·금리 고정 가정', '줄지 않음', '상환액 ≤ 1년 이자');
        else if (po) row('다 갚기까지', '소득·금리 고정 가정', po.years === 1 ? '1년 안' : '약 ' + po.years + '년', '총 ' + won(po.paid) + ' 상환');
      }

      var warn = $('[data-warn]');
      warn.hidden = true;
      var label = year + '년 소득분 · ' + (type === 'w' ? '근로소득자' : '종합소득자');
      $('[data-main-label]').textContent = label + ' · 1년 의무상환액';
      if (annual === 0) {
        $('[data-big]').innerHTML = '0<small>원</small>';
        $('[data-badge]').textContent = '의무상환 대상이 아니에요';
        $('[data-sub]').textContent = '소득금액 ' + won(income) + '이 상환기준소득 ' + man(c.base) + ' 이하예요. 원하면 언제든 자발적으로 갚을 수 있어요.';
      } else {
        $('[data-big]').innerHTML = comma(annual) + '<small>원</small>';
        if (type === 'w') {
          $('[data-badge]').textContent = annual < MIN_WITHHOLD ? '통지서로 직접 납부' : '월급에서 매달 약 ' + won(monthly);
          $('[data-sub]').textContent = annual < MIN_WITHHOLD ? '의무상환액이 36만원 미만이면 회사 원천공제 없이 납부통지서 기한까지 직접 내요.' : (year === '2025' ? '2026년 7월부터 2027년 6월까지' : '2027년 7월부터 1년 동안') + ' 12번 나눠 빠져요. 미리 한 번에 낼 수도 있어요.';
        } else {
          $('[data-badge]').textContent = '종합소득세 신고 후 국세청 고지';
          $('[data-sub]').textContent = (+year + 1) + '년 5월 종합소득세 신고 뒤 국세청이 결정·고지한 금액을 고지서 기한까지 내요.';
        }
        if (capped) { warn.textContent = '계산된 의무상환액(' + won(raw) + ')이 남은 잔액보다 많아서, 잔액 ' + won(bal) + '만 갚으면 끝나요.'; warn.hidden = false; }
        else if (po && po.never) { warn.textContent = '1년 의무상환액이 1년 이자(약 ' + won(Math.floor(bal * rate)) + ')보다 적어서 이 조건이 계속되면 잔액이 줄지 않아요. 자발적 상환을 함께 고려해 보세요.'; warn.hidden = false; }
      }

      var lines = [];
      if (type === 'w') lines.push('소득금액 = ' + won(inc) + ' − 근로소득공제 ' + won(ded) + ' = ' + won(income));
      lines.push('의무상환액 = (' + won(income) + ' − ' + man(c.base) + ') × ' + pct + '% = ' + won(raw) + (income <= c.base ? ' (기준 이하라 0원)' : ''));
      if (capped) lines.push('잔액 ' + won(bal) + '보다 많아서 잔액만큼만 상환');
      if (type === 'w' && annual >= MIN_WITHHOLD) lines.push('월 원천공제 ≈ ' + won(annual) + ' ÷ 12 = ' + won(monthly));
      if (po && !po.never) lines.push('잔액 ' + won(bal) + '에 매년 연 ' + (+rRaw) + '% 이자를 더하고 ' + won(annual) + '씩 갚으면 약 ' + po.years + '년');
      var box = $('[data-formula]');
      box.innerHTML = '';
      lines.forEach(function (t) { var p = document.createElement('p'); p.textContent = t; box.appendChild(p); });

      lastText = '[학자금대출 의무상환액 계산 결과] ' + label +
        (type === 'w' ? '\n연 총급여: ' + won(inc) + '\n근로소득공제: ' + won(ded) : '') +
        '\n연간 소득금액: ' + won(income) + '\n상환기준소득: ' + man(c.base) +
        '\n연 의무상환액(' + pct + '%): ' + won(annual) + (capped ? ' (잔액 한도)' : '') +
        (type === 'w' && annual >= MIN_WITHHOLD ? '\n월 원천공제액: 약 ' + won(monthly) : '') +
        (bal ? '\n대출 잔액: ' + won(bal) + ' (연 ' + (+rRaw) + '%)' : '') +
        (po ? (po.never ? '\n다 갚기까지: 이 조건으로는 잔액이 줄지 않음' : '\n다 갚기까지: 약 ' + po.years + '년 (소득·금리 고정 가정)') : '');
      result.classList.add('kst-show');
    }

    function money(inp) {
      inp.addEventListener('input', function () {
        var v = inp.value.replace(/\D/g, '').replace(/^0+(?=\d)/, '').slice(0, 11);
        inp.value = v ? comma(v) : '';
        calc();
      });
    }
    money(incI); money(balI);
    rateI.addEventListener('input', function () {
      var v = rateI.value.replace(/[^\d.]/g, '').replace(/(\..*)\./g, '$1').slice(0, 5);
      if (v !== rateI.value) rateI.value = v;
      syncChips(); calc();
    });

    function syncChips() {
      $$('[data-r]').forEach(function (b) { b.classList.toggle('kst-on', String(rateI.value).trim() !== '' && +b.getAttribute('data-r') === +rateI.value); });
      $$('[data-pct]').forEach(function (b) { b.classList.toggle('kst-on', +b.getAttribute('data-pct') === pct); });
    }
    $$('[data-r]').forEach(function (b) { b.addEventListener('click', function () { rateI.value = b.getAttribute('data-r'); syncChips(); calc(); }); });
    $$('[data-pct]').forEach(function (b) { b.addEventListener('click', function () { pct = +b.getAttribute('data-pct'); syncChips(); calc(); }); });

    function seg(attr, val) {
      $$('[' + attr + ']').forEach(function (b) { var on = b.getAttribute(attr) === val; b.classList.toggle('kst-on', on); b.setAttribute('aria-pressed', on); });
    }
    function setYear(y) { year = y; seg('data-year', y); $('[data-year-hint]').textContent = R[y].hint; calc(); }
    function setType(t) {
      type = t; seg('data-type', t);
      $('[data-inc-label]').innerHTML = t === 'w' ? '연 총급여 <small>(세전, 비과세 제외)</small>' : '연간 소득금액 <small>(수입 − 필요경비)</small>';
      $('[data-inc-hint]').textContent = t === 'w' ? '연봉에서 식대 같은 비과세 수당을 뺀 금액이에요. 근로소득공제를 자동으로 빼서 소득금액을 구해요.' : '종합소득세 신고서의 종합소득금액(사업·근로·연금·기타소득 등의 소득금액 합계)을 넣어 주세요.';
      incI.placeholder = t === 'w' ? '35,000,000' : '25,000,000';
      calc();
    }
    $$('[data-year]').forEach(function (b) { b.addEventListener('click', function () { setYear(b.getAttribute('data-year')); }); });
    $$('[data-type]').forEach(function (b) { b.addEventListener('click', function () { setType(b.getAttribute('data-type')); }); });

    $('[data-reset]').addEventListener('click', function () {
      incI.value = balI.value = ''; rateI.value = '1.7'; pct = 20;
      syncChips(); setType('w'); setYear('2026');
      hide(''); incI.focus();
    });

    $('[data-copy]').addEventListener('click', function () {
      var btn = this;
      function done() { btn.textContent = '복사됐어요 ✓'; setTimeout(function () { btn.textContent = '결과 복사'; }, 1500); }
      function fallback() { var ta = document.createElement('textarea'); ta.value = lastText; ta.setAttribute('readonly', ''); ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} ta.remove(); done(); }
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(lastText).then(done, fallback);
      else fallback();
    });

    syncChips();
    setYear('2026');
  })();
  </script>
</div>
<!-- 학자금대출 의무상환액 계산기 위젯 끝 -->

<h2>학자금대출 의무상환액 계산법</h2>
<p>취업 후 상환 학자금대출(ICL)은 소득이 일정 수준을 넘을 때부터 갚는 대출이에요. 그 기준선이 <strong>상환기준소득</strong>이고, 교육부가 해마다 고시해요. 국세청이 전년도 소득으로 의무상환액을 계산해 통지해요.</p>
<ol>
  <li><strong>연간 소득금액</strong> = 총급여 − 근로소득공제 (근로소득자). 사업소득 등 종합소득이 있으면 수입에서 필요경비를 뺀 소득금액을 합쳐요.</li>
  <li><strong>의무상환액</strong> = (연간 소득금액 − 상환기준소득) × 상환율 20% (대학원 대출은 25%)</li>
  <li>의무상환액은 남은 대출 원리금보다 많을 수 없어요. 그 해에 자발적으로 미리 갚은 금액은 빼고 통지돼요.</li>
</ol>
<p>예를 들어 2026년 총급여가 3,500만원인 근로소득자라면 이렇게 계산해요.</p>
<ul>
  <li>근로소득공제: 750만원 + (3,500만원 − 1,500만원) × 15% = 1,050만원</li>
  <li>소득금액: 3,500만원 − 1,050만원 = 2,450만원</li>
  <li>의무상환액: (2,450만원 − 2,056만원) × 20% = <strong>788,000원</strong></li>
  <li>월 원천공제: 788,000원 ÷ 12 = <strong>약 65,666원</strong> (2027년 7월부터 2028년 6월까지 매달)</li>
</ul>
<p>남은 잔액이 1,500만원이고 금리 연 1.7%, 소득이 그대로라고 가정하면 다 갚기까지 약 24년이 걸려요. 연봉이 오르면 의무상환액도 커져서 실제로는 더 빨리 끝나는 경우가 많아요.</p>

<h2>연봉별 학자금 의무상환액 (학부 대출 20%)</h2>
<p>근로소득만 있는 경우 총급여별 1년 의무상환액과 월 원천공제액이에요. 근로소득공제는 소득세법 제47조 기준으로 계산했어요.</p>
